-- =============================================================================
-- 01_bundle_development.sql — GENERATED by scripts/build-apply-bundle.sh
-- DO NOT EDIT BY HAND. Regenerate it from supabase/migrations/.
--
-- FOR THE AgentOS-DEVELOPMENT PROJECT ONLY. Run 00_preflight.sql first and
-- confirm the project in the dashboard. Run 02_verify.sql afterwards.
--
-- One transaction. If any statement fails, NOTHING is applied.
-- =============================================================================

begin;

-- Refuse to run on a project that already has AgentOS installed. Applying twice
-- would fail part-way on "type already exists"; refusing up front is clearer
-- and guarantees the transaction never starts modifying anything.
do $$
begin
  if to_regclass('public.organizations') is not null
     or exists (select 1 from pg_type t join pg_namespace n on n.oid = t.typnamespace
                where n.nspname = 'public' and t.typname = 'org_role') then
    raise exception 'AgentOS is already installed in this database - refusing to apply the bundle';
  end if;
  if to_regclass('auth.users') is null then
    raise exception 'auth.users does not exist - this does not look like a Supabase project';
  end if;
end;
$$;


-- ===========================================================================
-- >>> 0001_identity_tenancy.sql
-- ===========================================================================

-- =============================================================================
-- 0001_identity_tenancy.sql — P1 identity and multi-tenancy schema
--
-- Source of truth: DATA_MODEL.md "Identity/tenancy" + "Usage and operations".
--
-- NOT APPLIED. Written for owner review. Applying this to any Supabase project
-- requires explicit owner approval (CLAUDE.md rule 3).
--
-- Design notes that differ from a naive implementation:
--
--   * No extensions are required. `gen_random_uuid()` is built into PostgreSQL 13+,
--     and token hashing happens in Node (see 0005), so neither pgcrypto nor citext
--     is needed. That keeps this file portable between the local verification
--     cluster and Supabase, and avoids operator-resolution hazards inside
--     SECURITY DEFINER functions that run with `search_path = ''`.
--
--   * Case-insensitive text (slug, email) is stored normalised to lower case and
--     enforced with a CHECK, instead of using citext. Comparisons are then plain
--     `text` equality, which resolves correctly under an empty search_path.
--
--   * Financial/quota fields are integers. No floating point anywhere.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Enums
--
-- DATA_MODEL.md names these columns but specifies no values; the values below are
-- the owner-approved set (see docs/adr/0006-p1-schema-additions.md).
-- -----------------------------------------------------------------------------

create type public.org_role as enum ('owner', 'admin', 'member', 'viewer');

create type public.org_status as enum ('active', 'suspended');

create type public.invitation_status as enum ('pending', 'accepted', 'revoked', 'expired');

create type public.platform_admin_role as enum ('support', 'operator', 'superadmin');

create type public.actor_type as enum ('user', 'platform_admin', 'system');

-- -----------------------------------------------------------------------------
-- organizations
-- -----------------------------------------------------------------------------

create table public.organizations (
  id         uuid primary key default gen_random_uuid(),

  -- Unique, URL-safe and lower-case from day one. This is what a future migration
  -- to org-scoped URLs (/app/[orgSlug]/...) would use; see ADR-0005.
  slug       text not null
             constraint organizations_slug_format
             check (slug = lower(slug) and slug ~ '^[a-z0-9](?:[a-z0-9-]{0,38}[a-z0-9])?$'),

  name       text not null
             constraint organizations_name_length
             check (length(btrim(name)) between 2 and 120),

  locale     text not null default 'he'
             constraint organizations_locale_supported check (locale in ('he', 'en')),

  timezone   text not null default 'Asia/Jerusalem',

  status     public.org_status not null default 'active',

  -- Seat quota source for P1 only. The billing entitlement engine arrives in P5 and
  -- becomes the authority then (ADR-0006). Customers must never be able to raise this:
  -- 0003 withholds the UPDATE column privilege on it.
  --
  -- The default is 5, matching the Business tier's "Included org seats" in
  -- BILLING_AND_PLANS.md. A default of 1 would consume the only seat on the owner
  -- and make invitations — a core P1 deliverable — unusable out of the box, while
  -- protecting revenue that does not exist until P5.
  seat_limit integer not null default 5
             constraint organizations_seat_limit_positive check (seat_limit >= 1),

  created_at timestamptz not null default now(),

  constraint organizations_slug_unique unique (slug)
);

comment on column public.organizations.seat_limit is
  'P1 seat quota. Replaced by the P5 entitlement resolver. Not customer-updatable.';

-- -----------------------------------------------------------------------------
-- memberships
--
-- The authority for tenant access. Every RLS policy in this schema resolves
-- membership through this table (decision 1: SECURITY DEFINER + subquery).
-- -----------------------------------------------------------------------------

create table public.memberships (
  org_id     uuid not null references public.organizations (id) on delete cascade,
  user_id    uuid not null references auth.users (id) on delete cascade,
  role       public.org_role not null,
  created_at timestamptz not null default now(),

  -- Satisfies DATA_MODEL.md's UNIQUE(org_id, user_id) and serves is_org_member().
  primary key (org_id, user_id)
);

-- Required by decision 1 so the membership subquery stays index-only.
create index memberships_user_org_idx on public.memberships (user_id, org_id);

-- Serves the owner-count invariant in 0004 and member lists filtered by role.
create index memberships_org_role_idx on public.memberships (org_id, role);

-- -----------------------------------------------------------------------------
-- profiles
--
-- Exists so a `viewer` can see who is in the organisation (display name + role)
-- without being granted any access to email addresses, which live in auth.users
-- and stay unreadable to clients. See ADR-0006.
-- -----------------------------------------------------------------------------

create table public.profiles (
  user_id      uuid primary key references auth.users (id) on delete cascade,
  display_name text not null
               constraint profiles_display_name_length
               check (length(btrim(display_name)) between 1 and 80),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- invitations
--
-- Independent of Supabase's inviteUserByEmail(), which carries no org, role, seat
-- or expiry semantics. DATA_MODEL.md mandates token_hash, expires_at and status.
-- -----------------------------------------------------------------------------

create table public.invitations (
  id          uuid primary key default gen_random_uuid(),

  org_id      uuid not null references public.organizations (id) on delete cascade,

  email       text not null
              constraint invitations_email_normalised
              check (email = lower(email) and position('@' in email) > 1),

  -- Ownership is transferred, never invited. Enforced here as well as in 0003,
  -- so no code path can create an owner invitation.
  role        public.org_role not null
              constraint invitations_role_not_owner
              check (role in ('admin', 'member', 'viewer')),

  -- SHA-256 of the raw token, computed in Node. The raw token never reaches the
  -- database, so it cannot appear in pg_stat_statements, query logs or errors.
  -- The length check makes storing a raw token or a weaker digest impossible.
  token_hash  bytea not null
              constraint invitations_token_hash_is_sha256
              check (octet_length(token_hash) = 32),

  expires_at  timestamptz not null,

  status      public.invitation_status not null default 'pending',

  -- Cascade: an invitation issued by a deleted user must not stay live.
  invited_by  uuid not null references auth.users (id) on delete cascade,

  accepted_by uuid references auth.users (id) on delete set null,
  accepted_at timestamptz,
  revoked_at  timestamptz,
  created_at  timestamptz not null default now(),

  constraint invitations_token_hash_unique unique (token_hash),

  -- Enables composite (org_id, id) foreign keys in later phases, per DATA_MODEL.md.
  constraint invitations_org_id_unique unique (org_id, id),

  -- Status and its timestamps cannot disagree.
  constraint invitations_accepted_fields check (
    (status = 'accepted') = (accepted_by is not null and accepted_at is not null)
  ),
  constraint invitations_revoked_fields check (
    (status = 'revoked') = (revoked_at is not null)
  )
);

-- At most one live invitation per address per organisation. Prevents a quota being
-- padded with duplicates for the same person.
create unique index invitations_one_pending_per_email_idx
  on public.invitations (org_id, email)
  where status = 'pending';

create index invitations_org_status_created_idx
  on public.invitations (org_id, status, created_at desc);

-- -----------------------------------------------------------------------------
-- platform_admins
--
-- A platform-scoped allowlist, explicitly "not an org role" (DATA_MODEL.md).
-- 0003 enables RLS on it and creates NO policies, and revokes all table
-- privileges from anon/authenticated: no client can read it through PostgREST in
-- any role. It is reachable only from src/modules/platform-admin/ with the secret
-- key, where every read is audited.
-- -----------------------------------------------------------------------------

create table public.platform_admins (
  user_id      uuid primary key references auth.users (id) on delete cascade,
  role         public.platform_admin_role not null,

  -- Per-row, so MFA is enforced from database state rather than only from a
  -- project-wide Supabase setting. Defaults to required.
  mfa_required boolean not null default true,

  active       boolean not null default true,
  created_at   timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- audit_events — append only
--
-- Deliberately carries NO foreign keys. An audit record must survive the thing it
-- describes, and an ON DELETE SET NULL would be an UPDATE, which the immutability
-- trigger in 0004 forbids. org_id stays nullable so platform-level actions can be
-- logged without an organisation (DATA_MODEL.md).
-- -----------------------------------------------------------------------------

create table public.audit_events (
  id                uuid primary key default gen_random_uuid(),
  org_id            uuid,
  actor_user_id     uuid,
  actor_type        public.actor_type not null,

  action            text not null constraint audit_events_action_present check (btrim(action) <> ''),
  entity_type       text not null
                    constraint audit_events_entity_type_present check (btrim(entity_type) <> ''),
  entity_id         uuid,

  metadata_redacted jsonb not null default '{}'::jsonb,

  created_at        timestamptz not null default now(),

  -- A structural guard for SECURITY.md 7 and QUALITY_GATES.md "audit redaction
  -- checks": an audit row physically cannot carry a credential-shaped key.
  constraint audit_events_no_secret_keys check (
    not (metadata_redacted ?| array[
      'token', 'token_hash', 'raw_token', 'password', 'secret',
      'api_key', 'apikey', 'authorization', 'access_token', 'refresh_token'
    ])
  )
);

create index audit_events_org_created_idx on public.audit_events (org_id, created_at desc);
create index audit_events_actor_created_idx on public.audit_events (actor_user_id, created_at desc);

comment on table public.audit_events is
  'Append only. No UPDATE/DELETE privilege or policy exists; 0004 adds a trigger that '
  'blocks both even for the table owner.';


-- ===========================================================================
-- >>> 0002_rls_helpers.sql
-- ===========================================================================

-- =============================================================================
-- 0002_rls_helpers.sql — membership resolution for RLS (approved decision 1)
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
--
-- Decision 1: membership is resolved by querying the database, not by reading a
-- claim out of the JWT. The consequence that matters commercially is that removing
-- a member revokes access immediately, instead of when their access token happens
-- to refresh. SECURITY.md classes a cross-tenant leak as a release blocker, and a
-- stale-token window is exactly such a leak.
--
-- Every function here follows four rules, each a security requirement:
--
--   1. `set search_path = ''` with fully-qualified names. Without it the caller
--      controls search_path and can shadow `public.memberships` with their own
--      table, which in a SECURITY DEFINER function means privilege escalation.
--
--   2. `security definer` is what makes a policy on `memberships` able to read
--      `memberships` without infinite recursion: the body runs as the table owner,
--      for whom RLS is not applied. This is why `force row level security` must
--      NEVER be set on public.memberships — doing so reintroduces the recursion.
--      0004 and tests/db assert that it is off.
--
--   3. `(select auth.uid())` rather than a bare `auth.uid()`. The subselect is
--      cached as an InitPlan and evaluated once per statement instead of once per
--      row; this is what keeps the subquery approach cheap.
--
--   4. `stable`, so results can be reused within a statement.
--
-- EXECUTE is revoked from public/anon and granted only to `authenticated`.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- is_org_member — the base tenancy predicate
-- -----------------------------------------------------------------------------

create or replace function public.is_org_member(p_org_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.memberships m
    where m.org_id = p_org_id
      and m.user_id = (select auth.uid())
  );
$$;

comment on function public.is_org_member(uuid) is
  'True when the current user holds any membership in the organisation.';

-- -----------------------------------------------------------------------------
-- has_org_role — role-gated tenancy predicate
-- -----------------------------------------------------------------------------

create or replace function public.has_org_role(p_org_id uuid, p_roles public.org_role[])
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.memberships m
    where m.org_id = p_org_id
      and m.user_id = (select auth.uid())
      and m.role = any (p_roles)
  );
$$;

comment on function public.has_org_role(uuid, public.org_role[]) is
  'True when the current user holds one of the given roles in the organisation.';

-- -----------------------------------------------------------------------------
-- shares_org_with — lets a member see co-members'' display names (not emails)
-- -----------------------------------------------------------------------------

create or replace function public.shares_org_with(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.memberships me
    join public.memberships other on other.org_id = me.org_id
    where me.user_id = (select auth.uid())
      and other.user_id = p_user_id
  );
$$;

-- -----------------------------------------------------------------------------
-- current_aal — Authenticator Assurance Level of the live session
--
-- 'aal2' means a second factor was verified for this session. Used by the
-- platform-admin guard and available to RESTRICTIVE policies in later phases.
-- Returns 'aal1' when the claim is absent so the function never yields NULL into
-- a boolean expression (NULL would make a policy neither true nor false).
-- -----------------------------------------------------------------------------

create or replace function public.current_aal()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select auth.jwt() ->> 'aal'), 'aal1');
$$;

-- -----------------------------------------------------------------------------
-- org_seats_taken — the seat accounting rule, in one place
--
-- Seats taken = active memberships + live pending invitations.
--
-- Counting pending invitations is what closes the main quota bypass: without it,
-- an organisation on a 5-seat plan could issue 100 invitations and have every one
-- of them accepted. Expired invitations do not hold a seat.
--
-- Callers MUST hold a row lock on the organisation first (see 0004); this function
-- only counts and makes no atomicity guarantee on its own.
-- -----------------------------------------------------------------------------

create or replace function public.org_seats_taken(p_org_id uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select
    (select count(*) from public.memberships m where m.org_id = p_org_id)
    +
    (select count(*)
       from public.invitations i
      where i.org_id = p_org_id
        and i.status = 'pending'
        and i.expires_at > now())
$$;

-- -----------------------------------------------------------------------------
-- log_audit — the only way a client-reachable path can write an audit row
--
-- SECURITY DEFINER so that `authenticated` needs no INSERT privilege on
-- audit_events. Combined with the append-only trigger in 0004, audit history
-- cannot be forged, amended or erased from a customer session.
-- -----------------------------------------------------------------------------

create or replace function public.log_audit(
  p_org_id      uuid,
  p_actor_type  public.actor_type,
  p_action      text,
  p_entity_type text,
  p_entity_id   uuid default null,
  p_metadata    jsonb default '{}'::jsonb
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  insert into public.audit_events (
    org_id, actor_user_id, actor_type, action, entity_type, entity_id, metadata_redacted
  )
  values (
    p_org_id, (select auth.uid()), p_actor_type, p_action, p_entity_type, p_entity_id,
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning id into v_id;

  return v_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- org_seat_usage — the ONLY seat figure a client may read
--
-- org_seats_taken() is internal (see the grants below): it takes an arbitrary
-- org UUID and would otherwise let any authenticated user probe the existence
-- and headcount of organisations they have nothing to do with.
--
-- This wrapper exposes the same number only to someone who administers that
-- organisation, which is what the team screen needs.
-- -----------------------------------------------------------------------------

create or replace function public.org_seat_usage(p_org_id uuid)
returns table (seats_taken integer, seat_limit integer)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.has_org_role(p_org_id, array['owner', 'admin']::public.org_role[]) then
    raise exception 'ORG_ACCESS_DENIED' using errcode = 'insufficient_privilege';
  end if;

  return query
    select public.org_seats_taken(p_org_id),
           o.seat_limit
    from public.organizations o
    where o.id = p_org_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- log_platform_audit — audit writer for the platform-admin boundary
--
-- log_audit() derives the actor from auth.uid(). The platform-admin module
-- connects with the secret key and therefore has NO JWT, so auth.uid() is null
-- and every admin action would be recorded with an unknown actor — which is
-- precisely the opposite of what SUPER_ADMIN.md's "audit with reason/time" and
-- SECURITY.md 6 require.
--
-- This variant takes the actor explicitly. It is granted ONLY to service_role,
-- never to anon or authenticated: a caller able to name any actor would be
-- able to pin their actions on someone else.
-- -----------------------------------------------------------------------------

create or replace function public.log_platform_audit(
  p_actor_user_id uuid,
  p_action        text,
  p_entity_type   text,
  p_org_id        uuid default null,
  p_entity_id     uuid default null,
  p_metadata      jsonb default '{}'::jsonb
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if p_actor_user_id is null then
    raise exception 'PLATFORM_AUDIT_REQUIRES_ACTOR'
      using errcode = 'not_null_violation',
            detail = 'A platform-admin audit row must name the acting administrator.';
  end if;

  insert into public.audit_events (
    org_id, actor_user_id, actor_type, action, entity_type, entity_id, metadata_redacted
  )
  values (
    p_org_id, p_actor_user_id, 'platform_admin', p_action, p_entity_type, p_entity_id,
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning id into v_id;

  return v_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Execute privileges
--
-- EXECUTE on a function defaults to PUBLIC, so every function is revoked first
-- and then granted back deliberately.
--
-- THREE functions MUST stay executable by `authenticated`, and not by oversight:
-- is_org_member, has_org_role and shares_org_with are called from inside RLS
-- policy expressions. Policies are evaluated with the privileges of the user
-- running the query, so revoking EXECUTE would make every policy fail with
-- "permission denied for function" and take the whole tenancy layer down.
-- Each of them only ever reports on the caller's own membership, so exposing
-- them discloses nothing about anyone else.
--
-- TWO functions are internal only:
--
--   log_audit        SECURITY DEFINER taking org_id, actor_type and action as
--                    free parameters. Granted to `authenticated` it would let
--                    any signed-in user forge an audit record in ANY
--                    organisation, and impersonate actor_type 'system' or
--                    'platform_admin'. That destroys the evidentiary value of
--                    the whole audit trail (SECURITY.md 6, "immutable logs").
--                    It is reachable only from the SECURITY DEFINER RPCs in
--                    0005, which run as the function owner and therefore need
--                    no grant.
--
--   org_seats_taken  Takes an arbitrary org UUID and returns a headcount, so it
--                    is an existence-and-size oracle for other tenants. The
--                    seat gate in 0004 calls it from SECURITY DEFINER trigger
--                    functions, which run as the owner, so revoking EXECUTE
--                    does not weaken the quota in any way. Clients use the
--                    membership-checked org_seat_usage() wrapper above.
-- -----------------------------------------------------------------------------

revoke execute on function public.is_org_member(uuid) from public, anon, authenticated;
revoke execute on function public.has_org_role(uuid, public.org_role[]) from public, anon, authenticated;
revoke execute on function public.shares_org_with(uuid) from public, anon, authenticated;
revoke execute on function public.current_aal() from public, anon, authenticated;
revoke execute on function public.org_seats_taken(uuid) from public, anon, authenticated;
revoke execute on function public.org_seat_usage(uuid) from public, anon, authenticated;
revoke execute on function public.log_audit(
  uuid, public.actor_type, text, text, uuid, jsonb
) from public, anon, authenticated;

-- Required by RLS policy expressions.
grant execute on function public.is_org_member(uuid) to authenticated;
grant execute on function public.has_org_role(uuid, public.org_role[]) to authenticated;
grant execute on function public.shares_org_with(uuid) to authenticated;
-- Reads only the caller's own session claim.
grant execute on function public.current_aal() to authenticated;
-- Membership-checked seat figure.
grant execute on function public.org_seat_usage(uuid) to authenticated;

-- public.log_audit and public.org_seats_taken are intentionally NOT granted to
-- anon or authenticated. Do not add such a grant without re-reading the note
-- above: it would let any signed-in user forge audit records.

-- service_role is the trusted internal identity, reachable only with the secret
-- key from src/modules/platform-admin/. SUPER_ADMIN.md requires every privileged
-- admin action to be audited, so that module must be able to write audit rows.
-- This is the designed trust boundary, not a hole in it: the forgery risk came
-- from exposing log_audit to ordinary sessions, which remains closed.
grant execute on function public.log_audit(
  uuid, public.actor_type, text, text, uuid, jsonb
) to service_role;

-- Naming an arbitrary actor is a privilege reserved for the trusted internal
-- identity. anon and authenticated must never reach this.
revoke execute on function public.log_platform_audit(
  uuid, text, text, uuid, uuid, jsonb
) from public, anon, authenticated;
grant execute on function public.log_platform_audit(
  uuid, text, text, uuid, uuid, jsonb
) to service_role;


-- ===========================================================================
-- >>> 0003_rls_policies.sql
-- ===========================================================================

-- =============================================================================
-- 0003_rls_policies.sql — RLS and table privileges
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
--
-- Two independent mechanisms are used together, because RLS alone cannot express
-- "may edit this row but not this column":
--
--   * TABLE/COLUMN PRIVILEGES decide which columns a role may touch at all.
--     This is what stops an org owner raising their own `seat_limit` or clearing
--     their own `suspended` status: the privilege simply is not granted, so no
--     policy, API bug or direct PostgREST call can do it.
--
--   * ROW LEVEL SECURITY decides which rows are visible and writable.
--
-- Supabase configures default privileges that grant new tables in `public` to
-- `anon` and `authenticated`. Every table below therefore starts with an explicit
-- REVOKE ALL, so access is additive from zero rather than subtractive from full.
--
-- This is layer 4 of the five described in the P1 plan. Layers 1-3 (proxy,
-- resolveOrgContext, server permission guard) are independent checks in the
-- application, as DATA_MODEL.md requires: "RLS AND backend tenant membership
-- checks". Neither layer is allowed to be the only one.
-- =============================================================================

grant usage on schema public to anon, authenticated;

-- -----------------------------------------------------------------------------
-- organizations
-- -----------------------------------------------------------------------------

alter table public.organizations enable row level security;

revoke all on public.organizations from anon, authenticated;

grant select on public.organizations to authenticated;

-- Deliberately narrow. `seat_limit` and `status` are NOT updatable by customers:
-- the first is the P1 quota source, the second is a platform safety control.
-- Creating an organisation goes through the RPC in 0005, so no INSERT is granted.
grant update (name, locale, timezone) on public.organizations to authenticated;

create policy organizations_select on public.organizations
  for select to authenticated
  using (public.is_org_member(id));

create policy organizations_update on public.organizations
  for update to authenticated
  using (public.has_org_role(id, array['owner', 'admin']::public.org_role[]))
  with check (public.has_org_role(id, array['owner', 'admin']::public.org_role[]));

-- No DELETE policy and no DELETE privilege: organisations are suspended, never
-- deleted (SECURITY.md 4, SUPER_ADMIN.md "never silently delete").

-- -----------------------------------------------------------------------------
-- memberships
--
-- This is where privilege escalation would happen, so the three vectors from the
-- approved role matrix are blocked in the policy body:
--
--   USING      inspects the row as it is now  -> an admin cannot target an owner.
--   WITH CHECK inspects the row as it will be -> an admin cannot mint an admin.
--   user_id <> auth.uid()                     -> nobody edits their own role.
--
-- Only an owner may appoint or remove an admin, or touch an owner row. Ownership
-- transfer runs through the RPC in 0005 as a single transaction.
-- -----------------------------------------------------------------------------

alter table public.memberships enable row level security;

revoke all on public.memberships from anon, authenticated;

grant select on public.memberships to authenticated;
grant update (role) on public.memberships to authenticated;
grant delete on public.memberships to authenticated;

-- No INSERT privilege: memberships are created only by create_organization() and
-- accept_invitation() in 0005, both SECURITY DEFINER and both seat-gated.

create policy memberships_select on public.memberships
  for select to authenticated
  using (public.is_org_member(org_id));

create policy memberships_update on public.memberships
  for update to authenticated
  using (
    case
      when public.has_org_role(org_id, array['owner']::public.org_role[])
        then user_id <> (select auth.uid())
      when public.has_org_role(org_id, array['admin']::public.org_role[])
        then role in ('member', 'viewer') and user_id <> (select auth.uid())
      else false
    end
  )
  with check (
    case
      when public.has_org_role(org_id, array['owner']::public.org_role[])
        then user_id <> (select auth.uid())
      when public.has_org_role(org_id, array['admin']::public.org_role[])
        then role in ('member', 'viewer') and user_id <> (select auth.uid())
      else false
    end
  );

create policy memberships_delete on public.memberships
  for delete to authenticated
  using (
    case
      when public.has_org_role(org_id, array['owner']::public.org_role[])
        then user_id <> (select auth.uid())
      when public.has_org_role(org_id, array['admin']::public.org_role[])
        then role in ('member', 'viewer') and user_id <> (select auth.uid())
      else false
    end
  );

-- Note: self-removal ("leave organisation") is intentionally not possible in P1.
-- It needs its own confirmation flow and last-owner handling; deferred, not forgotten.

-- -----------------------------------------------------------------------------
-- profiles
--
-- Readable by co-members so a member list can show names. Email addresses are NOT
-- here — they stay in auth.users, which clients cannot read at all. That is what
-- lets a `viewer` see the team without being handed personal data.
-- -----------------------------------------------------------------------------

alter table public.profiles enable row level security;

revoke all on public.profiles from anon, authenticated;

grant select on public.profiles to authenticated;
grant update (display_name) on public.profiles to authenticated;

-- No INSERT privilege: rows are created by the handle_new_user() trigger in 0004.

create policy profiles_select on public.profiles
  for select to authenticated
  using (user_id = (select auth.uid()) or public.shares_org_with(user_id));

create policy profiles_update on public.profiles
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- -----------------------------------------------------------------------------
-- invitations
--
-- Not visible to `member` or `viewer` at all: the rows carry the email addresses
-- of people who have not joined, which is personal data no ordinary member needs.
--
-- The INSERT policy is the second place the "admin cannot invite an admin"
-- escalation is blocked (the first is the CHECK constraint in 0001).
--
-- Clients may only move an invitation to `revoked`. Accepting is done by the
-- SECURITY DEFINER RPC in 0005, so no session can accept an invitation addressed
-- to somebody else by flipping a status column.
-- -----------------------------------------------------------------------------

alter table public.invitations enable row level security;

revoke all on public.invitations from anon, authenticated;

grant select on public.invitations to authenticated;
grant insert (org_id, email, role, token_hash, expires_at, invited_by)
  on public.invitations to authenticated;
grant update (status, revoked_at) on public.invitations to authenticated;

create policy invitations_select on public.invitations
  for select to authenticated
  using (public.has_org_role(org_id, array['owner', 'admin']::public.org_role[]));

create policy invitations_insert on public.invitations
  for insert to authenticated
  with check (
    invited_by = (select auth.uid())
    and (
      public.has_org_role(org_id, array['owner']::public.org_role[])
      or (
        public.has_org_role(org_id, array['admin']::public.org_role[])
        and role in ('member', 'viewer')
      )
    )
  );

create policy invitations_revoke on public.invitations
  for update to authenticated
  using (
    status = 'pending'
    and public.has_org_role(org_id, array['owner', 'admin']::public.org_role[])
  )
  with check (
    status = 'revoked'
    and public.has_org_role(org_id, array['owner', 'admin']::public.org_role[])
  );

-- No DELETE: revocation is a status transition, so the record survives for audit.

-- -----------------------------------------------------------------------------
-- platform_admins — unreachable from any client session
--
-- RLS is enabled and NO policy is created, which denies everything by default.
-- Privileges are revoked as well, so the two mechanisms fail independently.
-- DATA_MODEL.md: "RLS never exposes platform_admin tables". The common pattern of
-- a policy that grants staff cross-org SELECT is explicitly ruled out there, so
-- platform reads go through an audited service method holding the secret key.
-- -----------------------------------------------------------------------------

alter table public.platform_admins enable row level security;

revoke all on public.platform_admins from anon, authenticated;

-- (intentionally no policies — RLS with zero policies denies every row)

-- service_role needs an EXPLICIT grant here.
--
-- BYPASSRLS bypasses row-level security, NOT table-level privileges. Without
-- this grant the platform-admin guard cannot read its own allowlist and the
-- /admin boundary fails closed for everyone, including real admins.
--
-- Relying on Supabase's implicit default grants instead would make the
-- behaviour depend on project configuration rather than on this migration,
-- and it would differ between Supabase and any other PostgreSQL. Stating it
-- here keeps the privilege model entirely in version control.
--
-- Read-only: rows are added by the owner through the documented setup step,
-- never by application code.
grant usage on schema public to service_role;
grant select on public.platform_admins to service_role;

-- -----------------------------------------------------------------------------
-- audit_events — readable by org administrators, writable by nobody
-- -----------------------------------------------------------------------------

alter table public.audit_events enable row level security;

revoke all on public.audit_events from anon, authenticated;

grant select on public.audit_events to authenticated;

-- No INSERT/UPDATE/DELETE privilege. Writes go through log_audit() (0002); 0004
-- adds a trigger that rejects UPDATE and DELETE even for the table owner.

create policy audit_events_select on public.audit_events
  for select to authenticated
  using (
    org_id is not null
    and public.has_org_role(org_id, array['owner', 'admin']::public.org_role[])
  );

-- Platform-level rows (org_id is null) match no policy, so no customer session can
-- read them regardless of role.


-- ===========================================================================
-- >>> 0004_invariants.sql
-- ===========================================================================

-- =============================================================================
-- 0004_invariants.sql — database-enforced invariants
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
--
-- Everything here guards against a state that must never exist, including under
-- concurrency. Application guards produce friendlier messages, but these are the
-- checks that actually hold: they apply to every path, including a direct
-- PostgREST call and a service-role script.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Invariant 1: every organisation keeps at least one owner
--
-- Why a plain `SELECT count(*)` in a trigger is NOT sufficient:
--
--   Under READ COMMITTED (PostgreSQL's default, and Supabase's), two concurrent
--   transactions each removing a *different* owner both read count = 2, both pass
--   the check, and both commit. The organisation ends up with zero owners.
--
-- The fix is the `FOR UPDATE` on the organisation row below. It is a serialisation
-- point: every membership change for a given organisation queues behind it, so the
-- second transaction re-reads the count only after the first has committed.
--
-- `DEFERRABLE INITIALLY DEFERRED` is what makes ownership transfer possible. The
-- check runs once at COMMIT rather than after each statement, so promoting the new
-- owner and demoting the previous one inside one transaction is legal, while
-- leaving the organisation ownerless is not.
-- -----------------------------------------------------------------------------

create or replace function public.assert_org_has_owner()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org_id      uuid;
  v_owner_count integer;
begin
  -- NEW is unassigned on DELETE and OLD on INSERT, so branch explicitly.
  if tg_op = 'DELETE' then
    v_org_id := old.org_id;
  else
    v_org_id := new.org_id;
  end if;

  -- Serialisation point. Also returns no row when the organisation itself was
  -- deleted and these memberships went with it by cascade — nothing to assert.
  perform 1 from public.organizations where id = v_org_id for update;
  if not found then
    return null;
  end if;

  select count(*) into v_owner_count
  from public.memberships
  where org_id = v_org_id
    and role = 'owner';

  if v_owner_count = 0 then
    raise exception 'ORG_REQUIRES_OWNER'
      using errcode = 'check_violation',
            detail = 'An organisation must always retain at least one owner.';
  end if;

  return null;
end;
$$;

create constraint trigger memberships_owner_guard
  after insert or update or delete on public.memberships
  deferrable initially deferred
  for each row execute function public.assert_org_has_owner();

-- -----------------------------------------------------------------------------
-- Invariant 2: the seat quota cannot be exceeded or raced
--
-- Applied to BOTH seat-consuming inserts, so the quota holds no matter which path
-- is used: issuing an invitation (which reserves a seat) and creating a membership.
--
-- It uses the same organisation-row lock as invariant 1, which means seat writes
-- and ownership writes serialise against each other on the same object.
--
-- Ordering requirement for the accept flow (see 0005): the invitation must be
-- marked `accepted` BEFORE the membership row is inserted. Otherwise the pending
-- invitation and the new membership would both count, and the final seat would be
-- rejected. `org_seats_taken` is STABLE and therefore sees the transaction's own
-- earlier writes.
-- -----------------------------------------------------------------------------

create or replace function public.enforce_seat_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_limit integer;
  v_taken integer;
begin
  select o.seat_limit into v_limit
  from public.organizations o
  where o.id = new.org_id
  for update;

  if not found then
    raise exception 'ORG_NOT_FOUND'
      using errcode = 'foreign_key_violation';
  end if;

  v_taken := public.org_seats_taken(new.org_id);

  -- BEFORE INSERT, so the incoming row is not yet counted.
  if v_taken >= v_limit then
    raise exception 'SEAT_LIMIT_REACHED'
      using errcode = 'check_violation',
            detail = format('seats_taken=%s seat_limit=%s', v_taken, v_limit);
  end if;

  return new;
end;
$$;

create trigger memberships_seat_gate
  before insert on public.memberships
  for each row execute function public.enforce_seat_limit();

create trigger invitations_seat_gate
  before insert on public.invitations
  for each row execute function public.enforce_seat_limit();

-- -----------------------------------------------------------------------------
-- Invariant 3: audit_events is append only
--
-- 0003 grants no UPDATE/DELETE privilege and creates no such policy, which already
-- stops customer sessions. This trigger is the layer that also stops the table
-- owner and any service-role script, satisfying SECURITY.md 6 "immutable logs".
--
-- Not SECURITY DEFINER: it needs no elevated rights to refuse.
-- -----------------------------------------------------------------------------

create or replace function public.audit_events_block_mutation()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'AUDIT_EVENTS_APPEND_ONLY'
    using errcode = 'insufficient_privilege',
          detail = 'audit_events is append-only: UPDATE and DELETE are never permitted.';
end;
$$;

create trigger audit_events_no_update
  before update on public.audit_events
  for each row execute function public.audit_events_block_mutation();

create trigger audit_events_no_delete
  before delete on public.audit_events
  for each row execute function public.audit_events_block_mutation();

-- -----------------------------------------------------------------------------
-- profiles: maintain updated_at server-side
-- -----------------------------------------------------------------------------

create or replace function public.touch_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

create trigger profiles_touch_updated_at
  before update on public.profiles
  for each row execute function public.touch_updated_at();

-- -----------------------------------------------------------------------------
-- Provision a profile for every new auth user
--
-- Runs as the definer because `authenticated` has no INSERT privilege on profiles.
-- The display name falls back to the local part of the address so a member list is
-- never blank; it is truncated to the column limit and never left empty.
-- -----------------------------------------------------------------------------

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (user_id, display_name)
  values (
    new.id,
    left(
      coalesce(
        nullif(btrim(new.raw_user_meta_data ->> 'display_name'), ''),
        nullif(split_part(coalesce(new.email, ''), '@', 1), ''),
        'user'
      ),
      80
    )
  )
  on conflict (user_id) do nothing;

  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- -----------------------------------------------------------------------------
-- Guard the assumption that decision 1 depends on
--
-- The RLS policies on public.memberships read public.memberships through a
-- SECURITY DEFINER helper. That is only non-recursive because RLS does not apply
-- to the table owner. Turning on FORCE ROW LEVEL SECURITY would reintroduce
-- infinite recursion and take the tenancy layer down. Fail the migration loudly
-- rather than discover it at runtime. tests/db asserts the same thing.
-- -----------------------------------------------------------------------------

-- -----------------------------------------------------------------------------
-- Trigger functions are internal
--
-- PostgreSQL does not check EXECUTE privilege when firing a trigger, so these
-- need no grant to work. EXECUTE still defaults to PUBLIC, though, and leaving
-- that in place means a client can call them directly. A direct call fails
-- ("can only be called as a trigger"), so the risk is low - but a SECURITY
-- DEFINER function should never be callable by anyone who has no business
-- calling it, and these take row locks on organizations.
-- -----------------------------------------------------------------------------

revoke execute on function public.assert_org_has_owner() from public, anon, authenticated;
revoke execute on function public.enforce_seat_limit() from public, anon, authenticated;
revoke execute on function public.audit_events_block_mutation() from public, anon, authenticated;
revoke execute on function public.touch_updated_at() from public, anon, authenticated;
revoke execute on function public.handle_new_user() from public, anon, authenticated;

do $$
begin
  if exists (
    select 1
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relname = 'memberships'
      and c.relforcerowsecurity
  ) then
    raise exception
      'FORCE ROW LEVEL SECURITY is enabled on public.memberships, which makes the '
      'RLS helper functions recurse. Disable it: '
      'ALTER TABLE public.memberships NO FORCE ROW LEVEL SECURITY;';
  end if;
end;
$$;


-- ===========================================================================
-- >>> 0005_rpc.sql
-- ===========================================================================

-- =============================================================================
-- 0005_rpc.sql — transactional operations that RLS alone cannot express
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
--
-- Each function here exists because the operation must be atomic across several
-- rows, or because it must act on behalf of a user who is not yet a member of the
-- organisation (and therefore matches no tenancy policy).
--
-- All are SECURITY DEFINER with `set search_path = ''`, and every one re-derives
-- the caller from `auth.uid()`. None of them accepts a caller identity, an org
-- membership or a role as an argument: API_CONTRACT.md requires that `org_id` is
-- "resolved from authenticated selected workspace and authorizations, never
-- blindly trusted from request body".
-- =============================================================================

-- -----------------------------------------------------------------------------
-- create_organization
--
-- Atomic because an organisation without an owner membership would be invisible
-- to its own creator: the SELECT policy requires membership. Two statements with
-- a failure between them would leak an unreachable row.
-- -----------------------------------------------------------------------------

create or replace function public.create_organization(p_name text, p_slug text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid    uuid := (select auth.uid());
  v_org_id uuid;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'insufficient_privilege';
  end if;

  if not exists (
    select 1 from auth.users u
    where u.id = v_uid and u.email_confirmed_at is not null
  ) then
    raise exception 'EMAIL_NOT_VERIFIED' using errcode = 'insufficient_privilege';
  end if;

  begin
    insert into public.organizations (name, slug)
    values (btrim(p_name), lower(btrim(p_slug)))
    returning id into v_org_id;
  exception
    when unique_violation then
      raise exception 'ORG_SLUG_TAKEN' using errcode = 'unique_violation';
  end;

  -- The creator is the first owner. The seat gate allows this: zero seats are
  -- taken at this point.
  insert into public.memberships (org_id, user_id, role)
  values (v_org_id, v_uid, 'owner');

  perform public.log_audit(
    v_org_id, 'user', 'organization.created', 'organization', v_org_id,
    jsonb_build_object('slug', lower(btrim(p_slug)))
  );

  return v_org_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- expire_stale_invitations
--
-- Moves pending invitations past their expiry to `expired`.
--
-- Needed because `invitations_one_pending_per_email_idx` is a partial unique index
-- on `status = 'pending'`, and an index predicate cannot reference now() (it must
-- be immutable). Without this sweep, an expired invitation would permanently block
-- re-inviting the same address.
--
-- Definer, so it re-checks authority itself rather than relying on RLS.
-- -----------------------------------------------------------------------------

create or replace function public.expire_stale_invitations(p_org_id uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count integer;
begin
  if (select auth.uid()) is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'insufficient_privilege';
  end if;

  if not public.has_org_role(p_org_id, array['owner', 'admin']::public.org_role[]) then
    raise exception 'ORG_ACCESS_DENIED' using errcode = 'insufficient_privilege';
  end if;

  update public.invitations
     set status = 'expired'
   where org_id = p_org_id
     and status = 'pending'
     and expires_at <= now();

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- -----------------------------------------------------------------------------
-- accept_invitation
--
-- Takes the SHA-256 digest, never the token. The raw token is hashed in Node, so
-- it never crosses the database boundary and cannot surface in
-- pg_stat_statements, query logs or error detail (owner condition 5 and 7).
--
-- Must be a definer function for two independent reasons: the accepting user is
-- not yet a member, so no tenancy policy matches them; and the seat check, the
-- membership insert and the single-use transition have to be one atomic unit.
--
-- Every rejection raises the SAME error. A message distinguishing "no such token"
-- from "expired" from "wrong address" would turn this into an oracle for
-- enumerating tokens and discovering who was invited where.
-- -----------------------------------------------------------------------------

create or replace function public.accept_invitation(p_token_hash bytea)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid      uuid := (select auth.uid());
  v_email    text;
  v_verified boolean;
  v_inv      public.invitations;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'insufficient_privilege';
  end if;

  select lower(u.email), (u.email_confirmed_at is not null)
    into v_email, v_verified
  from auth.users u
  where u.id = v_uid;

  -- Owner condition: only a signed-in user who has verified the address the
  -- invitation was sent to may accept it.
  if not coalesce(v_verified, false) then
    raise exception 'EMAIL_NOT_VERIFIED' using errcode = 'insufficient_privilege';
  end if;

  select * into v_inv
  from public.invitations
  where token_hash = p_token_hash
  for update;

  if not found
     or v_inv.status <> 'pending'
     or v_inv.expires_at <= now()
     or v_inv.email <> v_email
  then
    raise exception 'INVITATION_INVALID' using errcode = 'insufficient_privilege';
  end if;

  -- Single use. The row lock above already serialises concurrent attempts; the
  -- status predicate makes the transition itself conditional, so a replay after
  -- commit also fails.
  update public.invitations
     set status      = 'accepted',
         accepted_by = v_uid,
         accepted_at = now()
   where id = v_inv.id
     and status = 'pending';

  if not found then
    raise exception 'INVITATION_INVALID' using errcode = 'insufficient_privilege';
  end if;

  -- Ordering matters: the invitation is no longer `pending` above, so it no longer
  -- holds a seat when the seat gate evaluates the insert below.
  --
  -- An existing member consumes the invitation without a second membership row.
  -- Skipping the INSERT entirely also avoids running the seat gate for a seat that
  -- is already counted, which at the cap would reject a legitimate acceptance.
  if not exists (
    select 1 from public.memberships
    where org_id = v_inv.org_id and user_id = v_uid
  ) then
    insert into public.memberships (org_id, user_id, role)
    values (v_inv.org_id, v_uid, v_inv.role);
  end if;

  perform public.log_audit(
    v_inv.org_id, 'user', 'invitation.accepted', 'invitation', v_inv.id,
    jsonb_build_object('role', v_inv.role)
  );

  return v_inv.org_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- transfer_ownership
--
-- One transaction, so the organisation is never ownerless and never has two
-- owners by accident. The deferred owner guard from 0004 validates the end state
-- at COMMIT, which is exactly why that trigger is DEFERRABLE INITIALLY DEFERRED.
--
-- Only an owner may do this (approved role matrix), and it is the one operation
-- that changes the caller's own role.
-- -----------------------------------------------------------------------------

create or replace function public.transfer_ownership(p_org_id uuid, p_to_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'insufficient_privilege';
  end if;

  if not public.has_org_role(p_org_id, array['owner']::public.org_role[]) then
    raise exception 'ORG_ACCESS_DENIED' using errcode = 'insufficient_privilege';
  end if;

  if p_to_user_id = v_uid then
    raise exception 'ORG_ACCESS_DENIED' using errcode = 'insufficient_privilege';
  end if;

  if not exists (
    select 1 from public.memberships
    where org_id = p_org_id and user_id = p_to_user_id
  ) then
    raise exception 'ORG_ACCESS_DENIED' using errcode = 'insufficient_privilege';
  end if;

  update public.memberships
     set role = 'owner'
   where org_id = p_org_id and user_id = p_to_user_id;

  update public.memberships
     set role = 'admin'
   where org_id = p_org_id and user_id = v_uid;

  perform public.log_audit(
    p_org_id, 'user', 'organization.ownership_transferred', 'membership', null,
    jsonb_build_object('to_user_id', p_to_user_id)
  );
end;
$$;

-- -----------------------------------------------------------------------------
-- Execute privileges
-- -----------------------------------------------------------------------------

revoke execute on function public.create_organization(text, text) from public;
revoke execute on function public.expire_stale_invitations(uuid) from public;
revoke execute on function public.accept_invitation(bytea) from public;
revoke execute on function public.transfer_ownership(uuid, uuid) from public;

grant execute on function public.create_organization(text, text) to authenticated;
grant execute on function public.expire_stale_invitations(uuid) to authenticated;
grant execute on function public.accept_invitation(bytea) to authenticated;
grant execute on function public.transfer_ownership(uuid, uuid) to authenticated;


-- ===========================================================================
-- >>> 0006_agents.sql
-- ===========================================================================

-- =============================================================================
-- 0006_agents.sql — P2 agent definitions and their versions
--
-- Source of truth: DATA_MODEL.md "Agent + runtime" and "Integrity requirements";
-- PRD.md section 5 (Agent Studio); ROADMAP.md P2.
--
-- NOT APPLIED. Written for owner review. Applying this to any Supabase project
-- requires explicit owner approval (CLAUDE.md rule 3).
--
-- Two integrity rules from DATA_MODEL.md drive the whole shape of this file:
--
--   "Org foreign-key containment: a run cannot reference a different org's
--    agent/version"
--   "Published versions cannot be mutated in place"
--
-- Both are enforced here by keys rather than by application code. A composite
-- foreign key is checked by PostgreSQL on every write, including a write that
-- arrives directly through PostgREST with a forged body; a check in a route
-- handler is only as good as the route the caller happened to use.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Enum
--
-- 'draft'     — never published; freely editable.
-- 'published' — has at least one published version and an active one selected.
-- 'archived'  — withdrawn from use. NOT deleted: SECURITY.md 4 forbids silent
--               deletion of records that runs and invoices will refer back to.
-- -----------------------------------------------------------------------------

create type public.agent_status as enum ('draft', 'published', 'archived');

-- -----------------------------------------------------------------------------
-- agents
-- -----------------------------------------------------------------------------

create table public.agents (
  id                uuid primary key default gen_random_uuid(),
  org_id            uuid not null references public.organizations (id) on delete cascade,
  name              text not null check (length(trim(name)) between 2 and 120),
  description       text check (description is null or length(description) <= 500),
  status            public.agent_status not null default 'draft',
  -- Set only by publish_agent_version() in 0009. The foreign key that pins it to
  -- this agent is added at the bottom of this file, once agent_versions exists.
  active_version_id uuid,
  created_by        uuid references auth.users (id) on delete set null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),

  -- Redundant against the primary key, and deliberately so: it is the target a
  -- composite foreign key needs in order to carry org_id along. Every later
  -- table that points at an agent (team_members, runs, run_steps) will reference
  -- (org_id, id), so the database itself refuses a cross-org reference.
  constraint agents_org_id_key unique (org_id, id)
);

create index agents_org_status_created_idx
  on public.agents (org_id, status, created_at desc);

comment on column public.agents.active_version_id is
  'The published version this agent currently runs. NULL until first publish. '
  'Written only by publish_agent_version(); customers have no column privilege on it.';

-- -----------------------------------------------------------------------------
-- agent_versions
--
-- An immutable snapshot of an agent''s configuration once published. config_json
-- holds what PRD.md section 5 lists for Agent Studio: provider, model, prompt,
-- tool allowlist, max_steps, max_spend. Its shape is validated in the
-- application with Zod and will be schema-versioned in P3, when a runtime
-- actually reads it; the column is deliberately not constrained to one shape
-- here, because a CHECK on jsonb structure would have to be migrated in lockstep
-- with every config change.
-- -----------------------------------------------------------------------------

create table public.agent_versions (
  id           uuid primary key default gen_random_uuid(),
  org_id       uuid not null,
  agent_id     uuid not null,

  -- Nullable, and numbered only at publish time. Assigning a number when the
  -- draft is created would burn a number on every abandoned draft, and would
  -- make two people drafting at once collide on a number neither has published.
  version      integer check (version is null or version >= 1),
  config_json  jsonb not null default '{}'::jsonb,
  published_at timestamptz,
  created_by   uuid references auth.users (id) on delete set null,
  created_at   timestamptz not null default now(),

  -- Numbered exactly when published. The two states this allows are "draft"
  -- and "published"; a numbered draft or an unnumbered published version are
  -- both unrepresentable rather than merely unexpected.
  constraint agent_versions_numbered_when_published check (
    (published_at is null and version is null)
    or (published_at is not null and version is not null)
  ),

  -- DATA_MODEL.md: UNIQUE(agent_id, version). NULLs are distinct under a unique
  -- constraint, so this constrains published versions and leaves drafts alone.
  -- Version numbers are assigned under a row lock in 0009; this constraint is
  -- what makes that assignment safe rather than merely likely.
  constraint agent_versions_agent_version_key unique (agent_id, version),

  -- Org containment, enforced by the key: a version cannot be filed under a
  -- different organisation than the agent it belongs to. Without the composite
  -- reference, org_id here would be a free-text claim.
  constraint agent_versions_agent_fk
    foreign key (org_id, agent_id) references public.agents (org_id, id) on delete cascade,

  -- Targets for composite references from later tables, and from
  -- agents.active_version_id below.
  constraint agent_versions_org_id_key unique (org_id, id),
  constraint agent_versions_agent_id_key unique (agent_id, id)
);

create index agent_versions_org_agent_version_idx
  on public.agent_versions (org_id, agent_id, version desc);

-- Exactly one editable draft per agent, enforced rather than assumed. The RPCs
-- in 0009 maintain the invariant (publishing a draft immediately opens a fresh
-- one), and this index is what makes a bug in them fail loudly instead of
-- leaving two drafts that overwrite each other.
create unique index agent_versions_one_draft_per_agent
  on public.agent_versions (agent_id)
  where published_at is null;

-- Published versions, newest first: the lookup P3's runtime will make on every
-- dispatch. Partial, because unpublished drafts are never a dispatch target.
create index agent_versions_published_idx
  on public.agent_versions (agent_id, published_at desc)
  where published_at is not null;

-- -----------------------------------------------------------------------------
-- The active-version pointer
--
-- References (agent_id, id), not (org_id, id). That is the stronger of the two:
-- it rejects an agent pointing at some *other* agent's version, and org
-- containment then follows transitively, because agent_versions.agent_fk already
-- pins the version's org to the agent's org.
--
-- MATCH SIMPLE (the default) matters here: with active_version_id NULL the
-- constraint is not checked at all, which is what lets a draft agent exist with
-- no published version. MATCH FULL would reject every draft.
--
-- DEFERRABLE INITIALLY DEFERRED because the reference is circular: deleting an
-- agent cascades to its versions while the agent row still points at one of
-- them. Checking at commit, when both are gone, is the only ordering that works.
-- -----------------------------------------------------------------------------

alter table public.agents
  add constraint agents_active_version_fk
  foreign key (id, active_version_id) references public.agent_versions (agent_id, id)
  deferrable initially deferred;


-- ===========================================================================
-- >>> 0007_agents_rls.sql
-- ===========================================================================

-- =============================================================================
-- 0007_agents_rls.sql — RLS and table privileges for agents and agent_versions
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
--
-- Same two-mechanism approach as 0003: column privileges decide which columns a
-- role may touch at all, RLS decides which rows. Privileges are what stop a
-- customer writing active_version_id or published_at directly — no policy could
-- express that, and no application bug can grant it back.
--
-- Role matrix for agents (docs/adr/0008-p2-agent-schema.md):
--
--              read   create   edit draft   publish   archive
--   owner       yes     yes        yes        yes       yes
--   admin       yes     yes        yes        yes       yes
--   member      yes     yes        yes        yes       no
--   viewer      yes     no         no         no        no
--
-- member can publish. Agent Studio is the working surface of this product and a
-- team whose members cannot ship an agent would need an admin for every change;
-- spend is bounded by the per-run budget caps in P3, not by who pressed publish.
-- Archiving withdraws something other people may depend on, so it stays with
-- owner and admin.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- agents
-- -----------------------------------------------------------------------------

alter table public.agents enable row level security;

revoke all on public.agents from anon, authenticated;

grant select on public.agents to authenticated;

-- Narrow on purpose. Withheld, and why:
--   id, org_id      — identity; changing either would move the row between tenants
--   active_version_id — written only by publish_agent_version() in 0009
--   created_by, created_at — audit fields
--   updated_at      — maintained by a trigger in 0008, not by the client
-- No INSERT: agents are created by create_agent() in 0009, which also opens the
-- first draft. Two rows that must appear together are not two client calls.
--
-- status is absent from the UPDATE grant as well. 'published' is only true if
-- active_version_id points somewhere, and 'archived' is an owner/admin action;
-- both transitions belong to the RPCs, which set the pointer and the status in
-- one statement. Granting the column would let a client claim a state the data
-- does not support.
grant update (name, description) on public.agents to authenticated;

create policy agents_select on public.agents
  for select to authenticated
  using (public.is_org_member(org_id));

-- No INSERT policy, to match the withheld privilege. create_agent() is
-- SECURITY DEFINER and checks the caller's role itself.

-- USING tests the row as it stands, WITH CHECK the row as it would become. Both
-- are needed: without WITH CHECK a member could move an agent to another
-- organisation, and without USING they could edit one they cannot otherwise see.
--
-- Viewer is excluded by the role list, not by a column privilege: privileges are
-- per-table and cannot tell one member from another.
--
-- The status arm stops a member renaming an archived agent, which would present
-- a withdrawn agent as actively maintained.
create policy agents_update on public.agents
  for update to authenticated
  using (
    case
      when public.has_org_role(org_id, array['owner', 'admin']::public.org_role[]) then true
      when public.has_org_role(org_id, array['member']::public.org_role[])
        then status <> 'archived'
      else false
    end
  )
  with check (
    case
      when public.has_org_role(org_id, array['owner', 'admin']::public.org_role[]) then true
      when public.has_org_role(org_id, array['member']::public.org_role[])
        then status <> 'archived'
      else false
    end
  );

-- No DELETE policy and no DELETE privilege, for anyone. Agents are archived.
-- Runs, usage events and invoices in later phases refer back to the agent that
-- produced them; deleting the row would leave that history pointing at nothing.

-- -----------------------------------------------------------------------------
-- agent_versions
-- -----------------------------------------------------------------------------

alter table public.agent_versions enable row level security;

revoke all on public.agent_versions from anon, authenticated;

grant select on public.agent_versions to authenticated;

-- published_at is absent from both grants. Publishing is a state transition that
-- has to assign a version number and move the agent's pointer in the same
-- transaction, so it belongs to the RPC in 0009 and nowhere else. Without the
-- column privilege, a direct PostgREST call cannot forge it.
-- No INSERT either: drafts are opened by create_agent() and by
-- publish_agent_version(), which clones the version it just froze so editing can
-- continue. A client-side insert could create a second draft for the same agent
-- and race the unique index that forbids it.
--
-- version and published_at appear in no grant at all. Publishing has to assign a
-- number and move the agent's pointer in the same transaction, so it belongs to
-- the RPC in 0009 and nowhere else; without the privilege a direct PostgREST
-- call cannot forge either field.
grant update (config_json) on public.agent_versions to authenticated;

create policy agent_versions_select on public.agent_versions
  for select to authenticated
  using (public.is_org_member(org_id));

-- No INSERT policy, to match the withheld privilege.

-- Drafts only. The USING arm is the rule that matters: a row with published_at
-- set is not an updatable row for any customer role, whatever the columns say.
-- The trigger in 0008 enforces the same thing a second time, for connections
-- that are not subject to RLS at all.
create policy agent_versions_update on public.agent_versions
  for update to authenticated
  using (
    published_at is null
    and public.has_org_role(org_id, array['owner', 'admin', 'member']::public.org_role[])
  )
  with check (
    published_at is null
    and public.has_org_role(org_id, array['owner', 'admin', 'member']::public.org_role[])
  );

-- No DELETE: a published version is the record of what actually ran.


-- ===========================================================================
-- >>> 0008_agents_invariants.sql
-- ===========================================================================

-- =============================================================================
-- 0008_agents_invariants.sql — triggers that hold the agent model together
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
--
-- 0007 withholds the privileges and writes the policies that keep customers out
-- of published versions. This file enforces the same rule for connections RLS
-- does not constrain — the service role, the schema owner, a future background
-- job — because DATA_MODEL.md states it without qualification:
--
--   "Published versions cannot be mutated in place"
--
-- A rule that holds only for one class of connection is a convention, not an
-- invariant, and the row that eventually gets rewritten will be rewritten by the
-- connection that was exempt.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- A published agent version is frozen
--
-- UPDATE only, deliberately. There is no DELETE guard, and the reason is worth
-- recording: deleting an organisation cascades to its agents and from there to
-- their versions, and a trigger cannot tell a cascade from a direct delete. A
-- DELETE guard would therefore make an organisation undeletable — turning a rule
-- about editing history into a block on erasure requests. What stops a customer
-- deleting a version is the absence of the DELETE privilege in 0007, which no
-- cascade needs.
-- -----------------------------------------------------------------------------

create or replace function public.agent_versions_guard_mutation()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if old.published_at is not null then
    raise exception 'AGENT_VERSION_IMMUTABLE'
      using errcode = 'insufficient_privilege',
            detail = 'A published agent version is a record of what ran. '
                     'Publish a new version instead of editing this one.';
  end if;

  -- Identity columns, checked even while the row is still a draft. A draft that
  -- can change agent_id can be moved under another organisation's agent, and the
  -- composite foreign key would not object: the new (org_id, agent_id) pair is
  -- perfectly valid, just not this tenant's.
  if new.agent_id is distinct from old.agent_id
     or new.org_id is distinct from old.org_id
     or new.id is distinct from old.id then
    raise exception 'AGENT_VERSION_IDENTITY_IMMUTABLE'
      using errcode = 'insufficient_privilege',
            detail = 'id, org_id and agent_id cannot be reassigned.';
  end if;

  return new;
end;
$$;

create trigger agent_versions_guard
  before update on public.agent_versions
  for each row execute function public.agent_versions_guard_mutation();

-- -----------------------------------------------------------------------------
-- agents: identity columns, and updated_at
-- -----------------------------------------------------------------------------

create or replace function public.agents_guard_mutation()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.org_id is distinct from old.org_id or new.id is distinct from old.id then
    raise exception 'AGENT_IDENTITY_IMMUTABLE'
      using errcode = 'insufficient_privilege',
            detail = 'id and org_id cannot be reassigned.';
  end if;
  return new;
end;
$$;

create trigger agents_guard
  before update on public.agents
  for each row execute function public.agents_guard_mutation();

-- touch_updated_at is defined in 0004.
create trigger agents_touch_updated_at
  before update on public.agents
  for each row execute function public.touch_updated_at();


-- ===========================================================================
-- >>> 0009_agents_rpc.sql
-- ===========================================================================

-- =============================================================================
-- 0009_agents_rpc.sql — agent lifecycle operations
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
--
-- Same contract as 0005: SECURITY DEFINER, `set search_path = ''`, caller
-- re-derived from auth.uid(), and no function takes a role or a membership as an
-- argument. API_CONTRACT.md requires org_id to be "resolved from authenticated
-- selected workspace and authorizations, never blindly trusted from request
-- body"; every function below therefore derives the organisation from the agent
-- it was given, and then checks the caller against that.
--
-- These exist because each one spans rows that have to appear or change
-- together, and because 0007 deliberately grants no INSERT on either table.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- create_agent — a new agent and its first empty draft
--
-- Atomic because an agent with no draft is a dead end in the UI: there is
-- nothing to edit and no client-side way to open one, since INSERT on
-- agent_versions is granted to nobody.
-- -----------------------------------------------------------------------------

create or replace function public.create_agent(
  p_org_id      uuid,
  p_name        text,
  p_description text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid      uuid := (select auth.uid());
  v_agent_id uuid;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'insufficient_privilege';
  end if;

  if not public.has_org_role(
       p_org_id, array['owner', 'admin', 'member']::public.org_role[]
     ) then
    -- Same answer for "not a member" and "a viewer": a distinct error would
    -- tell an outsider that the organisation exists. ORG_ACCESS_DENIED is the
    -- existing code for this in API_CONTRACT.md's taxonomy.
    raise exception 'ORG_ACCESS_DENIED' using errcode = 'insufficient_privilege';
  end if;

  insert into public.agents (org_id, name, description, created_by)
  values (p_org_id, btrim(p_name), nullif(btrim(coalesce(p_description, '')), ''), v_uid)
  returning id into v_agent_id;

  insert into public.agent_versions (org_id, agent_id, config_json, created_by)
  values (p_org_id, v_agent_id, '{}'::jsonb, v_uid);

  perform public.log_audit(
    p_org_id, 'user', 'agent.created', 'agent', v_agent_id,
    jsonb_build_object('name', btrim(p_name))
  );

  return v_agent_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- publish_agent_version — freeze the draft, number it, point the agent at it,
-- and open a fresh draft from the same configuration
--
-- The row lock is the serialisation point, exactly as in the seat gate: two
-- concurrent publishes both reading max(version) without it would both compute
-- the same next number. One would then fail on the unique constraint, which is
-- correct but turns a routine action into an error the user did not cause.
-- Locking the agent first makes them queue instead.
--
-- Cloning a new draft keeps "exactly one draft per agent" true at every instant,
-- which is what the partial unique index in 0006 asserts. Without it, publishing
-- would consume the draft and the next edit would have nowhere to go.
-- -----------------------------------------------------------------------------

create or replace function public.publish_agent_version(p_agent_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid        uuid := (select auth.uid());
  v_org_id     uuid;
  v_status     public.agent_status;
  v_draft_id   uuid;
  v_config     jsonb;
  v_next       integer;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'insufficient_privilege';
  end if;

  -- FOR UPDATE: the serialisation point. Everything below reads state that a
  -- concurrent publish would otherwise be changing underneath it.
  select a.org_id, a.status into v_org_id, v_status
  from public.agents a
  where a.id = p_agent_id
  for update;

  -- "No such agent" and "not yours" give the same answer, as the invitation
  -- endpoints do. Separating them would confirm that a given agent id exists to
  -- someone who cannot otherwise see it.
  if v_org_id is null
     or not public.has_org_role(
          v_org_id, array['owner', 'admin', 'member']::public.org_role[]
        ) then
    raise exception 'ORG_ACCESS_DENIED' using errcode = 'insufficient_privilege';
  end if;

  if v_status = 'archived' then
    raise exception 'AGENT_ARCHIVED' using errcode = 'invalid_parameter_value';
  end if;

  select v.id, v.config_json into v_draft_id, v_config
  from public.agent_versions v
  where v.agent_id = p_agent_id and v.published_at is null;

  if v_draft_id is null then
    raise exception 'AGENT_VERSION_MISSING' using errcode = 'no_data_found';
  end if;

  -- An empty configuration is not publishable. P3 adds the real validation,
  -- when there is a runtime with an opinion about what a valid config contains;
  -- until then this at least refuses to freeze a version that does nothing, and
  -- the application validates the shape with Zod before it gets here.
  if v_config is null or v_config = '{}'::jsonb then
    raise exception 'AGENT_CONFIG_INVALID' using errcode = 'invalid_parameter_value';
  end if;

  select coalesce(max(v.version), 0) + 1 into v_next
  from public.agent_versions v
  where v.agent_id = p_agent_id;

  update public.agent_versions
  set version = v_next, published_at = now()
  where id = v_draft_id;

  -- The fresh draft carries the published configuration forward, so the next
  -- edit starts from what is live rather than from an empty object.
  insert into public.agent_versions (org_id, agent_id, config_json, created_by)
  values (v_org_id, p_agent_id, v_config, v_uid);

  update public.agents
  set active_version_id = v_draft_id, status = 'published'
  where id = p_agent_id;

  perform public.log_audit(
    v_org_id, 'user', 'agent.version_published', 'agent_version', v_draft_id,
    jsonb_build_object('agent_id', p_agent_id, 'version', v_next)
  );

  return jsonb_build_object('version_id', v_draft_id, 'version', v_next);
end;
$$;

-- -----------------------------------------------------------------------------
-- set_agent_archived — withdraw an agent from use, or restore it
--
-- owner and admin only (0007's matrix). Archiving withdraws something other
-- people's work may depend on; restoring puts it back into dispatch.
--
-- Restoring returns the agent to 'published' if it has an active version and to
-- 'draft' if it never published one. Returning it to 'published' with no active
-- version would be a state the data does not support.
-- -----------------------------------------------------------------------------

create or replace function public.set_agent_archived(p_agent_id uuid, p_archived boolean)
returns public.agent_status
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid       uuid := (select auth.uid());
  v_org_id    uuid;
  v_active    uuid;
  v_new       public.agent_status;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'insufficient_privilege';
  end if;

  select a.org_id, a.active_version_id into v_org_id, v_active
  from public.agents a
  where a.id = p_agent_id
  for update;

  if v_org_id is null
     or not public.has_org_role(v_org_id, array['owner', 'admin']::public.org_role[]) then
    raise exception 'ORG_ACCESS_DENIED' using errcode = 'insufficient_privilege';
  end if;

  if p_archived then
    v_new := 'archived';
  elsif v_active is not null then
    v_new := 'published';
  else
    v_new := 'draft';
  end if;

  update public.agents set status = v_new where id = p_agent_id;

  perform public.log_audit(
    v_org_id, 'user',
    case when p_archived then 'agent.archived' else 'agent.restored' end,
    'agent', p_agent_id, '{}'::jsonb
  );

  return v_new;
end;
$$;

-- -----------------------------------------------------------------------------
-- Execute privileges
--
-- PUBLIC is revoked explicitly: PostgreSQL grants EXECUTE to PUBLIC on every new
-- function by default, so a SECURITY DEFINER function is callable by anon until
-- someone says otherwise.
-- -----------------------------------------------------------------------------

revoke execute on function public.create_agent(uuid, text, text) from public;
revoke execute on function public.publish_agent_version(uuid) from public;
revoke execute on function public.set_agent_archived(uuid, boolean) from public;

grant execute on function public.create_agent(uuid, text, text) to authenticated;
grant execute on function public.publish_agent_version(uuid) to authenticated;
grant execute on function public.set_agent_archived(uuid, boolean) to authenticated;


-- ===========================================================================
-- >>> 0010_templates.sql
-- ===========================================================================

-- =============================================================================
-- 0010_templates.sql — the global template catalog and org installations
--
-- Source of truth: DATA_MODEL.md "Templates (global vs installation)";
-- PRD.md section 3; ROADMAP.md P2 ("install copy; unauthorized template
-- editing denied").
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
--
-- The security shape of this file is different from every table before it.
-- `agents` are tenant data: each organisation owns its rows and RLS decides
-- which. Templates are PLATFORM data, shared by every tenant, and a customer
-- must never write one — a template that one tenant could edit is a template
-- every other tenant installs. So:
--
--   * global_templates and global_template_versions grant SELECT and nothing
--     else to `authenticated`. No INSERT, no UPDATE, no DELETE, and no policy
--     for those commands exists to be mis-written later.
--   * Reads are filtered to what is actually offered: a published version of a
--     public template. A draft template being prepared by the platform is
--     invisible to customers, not merely unlisted in the UI.
--   * Installing copies the definition into the organisation. The installed
--     agent is ordinary tenant data from that moment on, which is what makes
--     editing it safe.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Enum
--
-- 'draft'   — being prepared by the platform. Invisible to every customer.
-- 'public'  — listed and installable.
-- 'retired' — withdrawn. Existing installations are untouched (they are copies),
--             but it is gone from the catalog and cannot be installed again.
-- -----------------------------------------------------------------------------

create type public.template_visibility as enum ('draft', 'public', 'retired');

-- -----------------------------------------------------------------------------
-- global_templates
--
-- No org_id: this table is not tenant data. That is also why it carries no
-- tenancy policy — `is_org_member` has nothing to be a member of here.
-- -----------------------------------------------------------------------------

create table public.global_templates (
  id                uuid primary key default gen_random_uuid(),
  slug              text not null unique
                      check (slug = lower(slug) and slug ~ '^[a-z][a-z0-9-]{1,62}$'),
  category          text not null check (length(trim(category)) between 2 and 60),
  name              text not null check (length(trim(name)) between 2 and 120),
  description       text not null check (length(trim(description)) between 10 and 1000),
  visibility        public.template_visibility not null default 'draft',
  active_version_id uuid,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),

  constraint global_templates_id_key unique (id)
);

create index global_templates_visible_idx
  on public.global_templates (category, name)
  where visibility = 'public';

-- -----------------------------------------------------------------------------
-- global_template_versions
--
-- "immutable" in DATA_MODEL.md, enforced the same way agent_versions is: a
-- trigger in this file, because there is no RLS policy to rely on — customers
-- cannot write here at all, so the only connection that could rewrite history
-- is the privileged one, which is exactly the one a policy would not stop.
-- -----------------------------------------------------------------------------

create table public.global_template_versions (
  id              uuid primary key default gen_random_uuid(),
  template_id     uuid not null references public.global_templates (id) on delete cascade,
  version         integer not null check (version >= 1),
  -- The agent configuration this template installs, in the shape
  -- AgentConfigSchema validates. Not CHECK-constrained here, for the same
  -- reason agent_versions.config_json is not: a jsonb structure constraint has
  -- to be migrated in lockstep with every change to the configuration.
  definition_json jsonb not null,
  -- Tool keys the template expects to exist. Advisory in P2 — there is no tool
  -- registry until P4 — so it is recorded, shown to the installer, and not
  -- enforced. Enforcing against a registry that does not exist would reject
  -- every template.
  required_tools  jsonb not null default '[]'::jsonb,
  published_at    timestamptz,
  created_at      timestamptz not null default now(),

  constraint global_template_versions_template_version_key unique (template_id, version),
  constraint global_template_versions_template_id_key unique (template_id, id)
);

create index global_template_versions_published_idx
  on public.global_template_versions (template_id, version desc)
  where published_at is not null;

-- Pins the active version to this template, not merely to some template.
alter table public.global_templates
  add constraint global_templates_active_version_fk
  foreign key (id, active_version_id)
  references public.global_template_versions (template_id, id)
  deferrable initially deferred;

-- -----------------------------------------------------------------------------
-- template_installations
--
-- Tenant data, unlike the two tables above. One row per install, kept as the
-- record of where an organisation's agent came from.
--
-- `linked_agent_id` is an addition to DATA_MODEL.md's column list, recorded in
-- docs/adr/0009-p2-template-catalog.md: the documented `linked_workflow_id` is
-- the P4 analogue, and without an agent link nothing connects an installation
-- to what it produced. Both are nullable, and both carry the organisation in a
-- composite foreign key so an installation cannot point at another tenant's row.
-- -----------------------------------------------------------------------------

create table public.template_installations (
  id                  uuid primary key default gen_random_uuid(),
  org_id              uuid not null references public.organizations (id) on delete cascade,
  template_version_id uuid not null references public.global_template_versions (id),
  linked_agent_id     uuid,
  -- P4. Declared now so the column list matches DATA_MODEL.md and the foreign
  -- key arrives with the workflows table rather than being retrofitted.
  linked_workflow_id  uuid,
  installed_by        uuid references auth.users (id) on delete set null,
  created_at          timestamptz not null default now(),

  constraint template_installations_agent_fk
    foreign key (org_id, linked_agent_id) references public.agents (org_id, id)
    on delete set null,
  constraint template_installations_org_id_key unique (org_id, id)
);

create index template_installations_org_created_idx
  on public.template_installations (org_id, created_at desc);

-- Not unique on (org_id, template_version_id): installing the same template
-- twice is a reasonable thing to do — two agents from one starting point — and
-- forbidding it would be a surprise with no safety value, since each install
-- produces an independent copy.


-- ===========================================================================
-- >>> 0011_templates_rls.sql
-- ===========================================================================

-- =============================================================================
-- 0011_templates_rls.sql — privileges and policies for the template catalog
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
--
-- ROADMAP.md's P2 gate includes "unauthorized template editing denied". That is
-- delivered here by granting no write privilege at all on the two platform
-- tables, rather than by a policy that denies writes: a missing privilege
-- cannot be re-enabled by adding a policy later without someone also writing
-- the GRANT, and the GRANT is the line a reviewer will notice.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- global_templates — platform data, read-only to every customer
-- -----------------------------------------------------------------------------

alter table public.global_templates enable row level security;

revoke all on public.global_templates from anon, authenticated;

grant select on public.global_templates to authenticated;
grant select, insert, update on public.global_templates to service_role;

-- 'draft' templates are invisible, not merely unlisted. A template the platform
-- is still writing must not be discoverable by a customer who guesses a URL or
-- queries PostgREST directly.
--
-- 'retired' is also excluded: it is gone from the catalog. Organisations that
-- already installed it keep their copy, which is the whole point of installing
-- by copy rather than by reference.
create policy global_templates_select on public.global_templates
  for select to authenticated
  using (visibility = 'public');

-- No INSERT, UPDATE or DELETE policy, matching the withheld privileges. The
-- platform writes these through the service role, which carries BYPASSRLS and
-- the grants above.

-- -----------------------------------------------------------------------------
-- global_template_versions — likewise
-- -----------------------------------------------------------------------------

alter table public.global_template_versions enable row level security;

revoke all on public.global_template_versions from anon, authenticated;

grant select on public.global_template_versions to authenticated;
grant select, insert, update on public.global_template_versions to service_role;

-- Two conditions, both necessary. Published, because an unpublished version is
-- work in progress; and belonging to a public template, because otherwise a
-- published version of a draft template would be readable through this table
-- even though the template itself is hidden — a side door around the policy
-- above.
create policy global_template_versions_select on public.global_template_versions
  for select to authenticated
  using (
    published_at is not null
    and exists (
      select 1 from public.global_templates t
      where t.id = template_id and t.visibility = 'public'
    )
  );

-- -----------------------------------------------------------------------------
-- template_installations — ordinary tenant data
-- -----------------------------------------------------------------------------

alter table public.template_installations enable row level security;

revoke all on public.template_installations from anon, authenticated;

grant select on public.template_installations to authenticated;

-- No INSERT: install_template() in 0012 creates the installation, the agent and
-- its draft in one transaction. An installation row written on its own would
-- claim an agent came from a template that was never copied.
--
-- No UPDATE and no DELETE: this is the record of where an agent came from.

create policy template_installations_select on public.template_installations
  for select to authenticated
  using (public.is_org_member(org_id));


-- ===========================================================================
-- >>> 0012_templates_rpc.sql
-- ===========================================================================

-- =============================================================================
-- 0012_templates_rpc.sql — installing a template
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
--
-- Same contract as 0005 and 0009: SECURITY DEFINER, `set search_path = ''`,
-- caller re-derived from auth.uid(), no role or membership accepted as an
-- argument.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- global_template_versions_guard_mutation — published versions are frozen
--
-- DATA_MODEL.md calls these versions immutable. Customers cannot write here at
-- all, so the only connection that could rewrite one is the privileged one —
-- precisely the connection a policy would not constrain. A trigger is the only
-- place the rule can actually live.
-- -----------------------------------------------------------------------------

create or replace function public.global_template_versions_guard_mutation()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if old.published_at is not null then
    raise exception 'TEMPLATE_VERSION_IMMUTABLE'
      using errcode = 'insufficient_privilege',
            detail = 'A published template version is what organisations installed. '
                     'Publish a new version instead of editing this one.';
  end if;
  if new.template_id is distinct from old.template_id or new.id is distinct from old.id then
    raise exception 'TEMPLATE_VERSION_IDENTITY_IMMUTABLE'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;

create trigger global_template_versions_guard
  before update on public.global_template_versions
  for each row execute function public.global_template_versions_guard_mutation();

create trigger global_templates_touch_updated_at
  before update on public.global_templates
  for each row execute function public.touch_updated_at();

-- -----------------------------------------------------------------------------
-- install_template — copy a template version into the organisation
--
-- "Installation creates an organisational copy" (PRD.md section 3). A copy, not
-- a reference: the organisation then edits its agent freely, and the platform
-- retiring or republishing the template cannot change what is already running
-- in someone's workspace.
--
-- Three rows in one transaction — the agent, its draft, and the installation
-- record — because any two of them without the third describes something that
-- did not happen.
-- -----------------------------------------------------------------------------

create or replace function public.install_template(
  p_org_id              uuid,
  p_template_version_id uuid,
  p_name                text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid        uuid := (select auth.uid());
  v_definition jsonb;
  v_template   uuid;
  v_name       text;
  v_agent_id   uuid;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'insufficient_privilege';
  end if;

  if not public.has_org_role(
       p_org_id, array['owner', 'admin', 'member']::public.org_role[]
     ) then
    raise exception 'ORG_ACCESS_DENIED' using errcode = 'insufficient_privilege';
  end if;

  -- The same two conditions the SELECT policy applies, restated because this
  -- function is SECURITY DEFINER and therefore not subject to that policy. A
  -- definer function that trusts its argument to have been filtered by RLS is
  -- the standard way a hidden row becomes reachable.
  select v.definition_json, v.template_id into v_definition, v_template
  from public.global_template_versions v
  join public.global_templates t on t.id = v.template_id
  where v.id = p_template_version_id
    and v.published_at is not null
    and t.visibility = 'public';

  if v_definition is null then
    -- Not found, not published, or the template is draft/retired: one answer,
    -- so this cannot be used to discover templates the platform is preparing.
    raise exception 'TEMPLATE_NOT_AVAILABLE' using errcode = 'no_data_found';
  end if;

  v_name := nullif(btrim(coalesce(p_name, v_definition ->> 'name', '')), '');
  if v_name is null or length(v_name) < 2 then
    raise exception 'VALIDATION_FAILED' using errcode = 'invalid_parameter_value';
  end if;
  v_name := left(v_name, 120);

  insert into public.agents (org_id, name, description, created_by)
  values (
    p_org_id,
    v_name,
    left(nullif(btrim(coalesce(v_definition ->> 'description', '')), ''), 500),
    v_uid
  )
  returning id into v_agent_id;

  -- The draft starts as the template's definition, so the installer opens a
  -- working configuration rather than an empty form. `name` is dropped: the
  -- agent row owns the name, and a stale copy inside the config would survive
  -- a later rename and reappear in the next published version.
  insert into public.agent_versions (org_id, agent_id, config_json, created_by)
  values (p_org_id, v_agent_id, v_definition - 'name', v_uid);

  insert into public.template_installations
    (org_id, template_version_id, linked_agent_id, installed_by)
  values (p_org_id, p_template_version_id, v_agent_id, v_uid);

  perform public.log_audit(
    p_org_id, 'user', 'template.installed', 'agent', v_agent_id,
    jsonb_build_object('template_id', v_template, 'template_version_id', p_template_version_id)
  );

  return v_agent_id;
end;
$$;

revoke execute on function public.install_template(uuid, uuid, text) from public;
grant execute on function public.install_template(uuid, uuid, text) to authenticated;


-- ===========================================================================
-- >>> 0013_runtime.sql
-- ===========================================================================

-- =============================================================================
-- 0013_runtime.sql — runs, steps, and the usage ledger
--
-- Source of truth: DATA_MODEL.md "Agent + runtime" and "Usage and operations";
-- ARCHITECTURE.md "Run lifecycle" and "Concurrency/resilience"; ROADMAP.md P3
-- ("caps, trace, retry/cancel, transactional provider-cost reservations,
-- usage ledger"; gate: "per-tenant spend cap and idempotency pass").
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
--
-- MONEY IS INTEGER MICROS, EVERYWHERE.
--
-- DATA_MODEL.md: "financial values as integer minor units or fixed precision
-- numeric; NEVER floating point for invoices". Its column sketch names these
-- `budget_usd` / `spent_usd`; every one of them is `*_usd_micros` here, as a
-- bigint count of millionths of a dollar.
--
-- Two reasons, both recorded in docs/adr/0010-p3-runtime-schema.md. A cent is
-- too coarse for per-token model pricing, where a single call can cost less
-- than $0.0001 and rounding each one to a cent would turn a real bill into
-- zero. And the unit belongs in the name: `budget_usd` holding 2000000 is a
-- bug waiting for someone to read it as two million dollars, which is a factor
-- of a million in the direction nobody notices until the invoice.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Per-tenant spend cap
--
-- The same shape as `seat_limit` in P1, for the same reason: ROADMAP.md's P3
-- gate requires a per-tenant spend cap, the entitlement engine that should
-- supply it is P5, and a cap with no source cannot be enforced. Replaced by
-- `entitlementResolver` in P5; NOT customer-updatable, because 0014 grants no
-- privilege on the column.
--
-- $50/month by default: generous enough that development and the first real
-- customers are not fighting it, small enough that a runaway loop stops.
-- -----------------------------------------------------------------------------

alter table public.organizations
  add column monthly_spend_cap_usd_micros bigint not null default 50000000
    check (monthly_spend_cap_usd_micros >= 0);

comment on column public.organizations.monthly_spend_cap_usd_micros is
  'P3 spend cap source, in millionths of a dollar. Replaced by plan entitlements in P5. '
  'Customers have no column privilege on it.';

-- -----------------------------------------------------------------------------
-- Enums
-- -----------------------------------------------------------------------------

-- 'awaiting_approval' is P4 (approval requests). Declared now because the only
-- safe moment to add an enum value is before anything depends on the set, and a
-- status a run can reach is not something to retrofit under load.
create type public.run_status as enum (
  'queued', 'running', 'awaiting_approval', 'succeeded', 'failed', 'cancelled'
);

create type public.run_step_kind as enum ('model_call', 'tool_call', 'approval', 'system');

create type public.run_step_status as enum (
  'pending', 'running', 'succeeded', 'failed', 'skipped'
);

-- 'active'   — holding budget that has not been spent.
-- 'settled'  — the run reported what it actually cost.
-- 'released' — the run ended without spending it (cancelled, failed early).
-- 'expired'  — nobody settled or released it before expires_at. The sweeper
--              reclaims these; without the state, a crashed worker would hold
--              an organisation's budget hostage forever.
create type public.usage_reservation_status as enum ('active', 'settled', 'released', 'expired');

-- -----------------------------------------------------------------------------
-- runs
-- -----------------------------------------------------------------------------

create table public.runs (
  id                 uuid primary key default gen_random_uuid(),
  org_id             uuid not null references public.organizations (id) on delete cascade,
  agent_id           uuid not null,
  -- The PUBLISHED version this run executes, pinned at dispatch. CLAUDE.md
  -- rule 8: "published version pin". Editing the draft afterwards, or
  -- publishing a newer version, must not change what a finished run did.
  agent_version_id   uuid not null,
  initiator_user_id  uuid references auth.users (id) on delete set null,
  status             public.run_status not null default 'queued',
  -- P4. Declared so the column list matches DATA_MODEL.md's `workflow_ref`;
  -- the foreign key arrives with the workflows table.
  workflow_version_id uuid,

  input_json         jsonb not null default '{}'::jsonb,
  result_json        jsonb,
  error_code         text check (error_code is null or length(error_code) between 1 and 64),

  -- ARCHITECTURE.md "Concurrency/resilience": idempotency keys. Unique per
  -- organisation, so a client that retries a dispatch it is unsure about gets
  -- the same run rather than a second one that also costs money.
  idempotency_key    text check (idempotency_key is null or length(idempotency_key) between 8 and 200),

  budget_usd_micros  bigint not null check (budget_usd_micros > 0),
  spent_usd_micros   bigint not null default 0 check (spent_usd_micros >= 0),

  created_at         timestamptz not null default now(),
  started_at         timestamptz,
  ended_at           timestamptz,

  -- A run that has ended has an end time, and one that has not, has not. Both
  -- halves matter: without the first, a finished run can report no duration;
  -- without the second, a running one can claim to have finished.
  constraint runs_ended_consistent check (
    (status in ('succeeded', 'failed', 'cancelled')) = (ended_at is not null)
  ),
  constraint runs_started_before_ended check (
    started_at is null or ended_at is null or ended_at >= started_at
  ),

  constraint runs_agent_fk
    foreign key (org_id, agent_id) references public.agents (org_id, id) on delete cascade,
  constraint runs_version_fk
    foreign key (org_id, agent_version_id)
    references public.agent_versions (org_id, id),
  constraint runs_org_id_key unique (org_id, id)
);

-- DATA_MODEL.md: "Provide indexes on (org_id,status,created_at) for runs".
create index runs_org_status_created_idx on public.runs (org_id, status, created_at desc);
create index runs_org_agent_created_idx on public.runs (org_id, agent_id, created_at desc);

-- Partial, so a run without a key costs nothing. NULLs are distinct under a
-- unique constraint anyway, but the partial index also keeps it small.
create unique index runs_org_idempotency_key
  on public.runs (org_id, idempotency_key)
  where idempotency_key is not null;

-- -----------------------------------------------------------------------------
-- run_steps — the trace
-- -----------------------------------------------------------------------------

create table public.run_steps (
  id               uuid primary key default gen_random_uuid(),
  org_id           uuid not null,
  run_id           uuid not null,
  step_index       integer not null check (step_index >= 0),
  kind             public.run_step_kind not null,
  status           public.run_step_status not null default 'pending',
  provider         text check (provider is null or length(provider) between 1 and 64),
  model            text check (model is null or length(model) between 1 and 120),
  -- What this step cost. Null while it is still running: zero would be a claim,
  -- and a claim of zero is the one that disappears from a bill.
  usage_usd_micros bigint check (usage_usd_micros is null or usage_usd_micros >= 0),
  -- A POINTER to a redacted trace, never the trace itself. SECURITY.md keeps
  -- prompt and completion content out of rows that support staff can read;
  -- DATA_MODEL.md calls the column `redacted_trace_ref` for the same reason.
  redacted_trace_ref text check (redacted_trace_ref is null or length(redacted_trace_ref) <= 400),
  -- Bounded, redacted summary for the trace view: step titles and counts, never
  -- prompt or completion text.
  summary_json     jsonb not null default '{}'::jsonb,
  error_code       text check (error_code is null or length(error_code) between 1 and 64),
  started_at       timestamptz,
  ended_at         timestamptz,
  created_at       timestamptz not null default now(),

  constraint run_steps_run_fk
    foreign key (org_id, run_id) references public.runs (org_id, id) on delete cascade,
  constraint run_steps_run_index_key unique (run_id, step_index),
  constraint run_steps_org_id_key unique (org_id, id)
);

create index run_steps_run_index_idx on public.run_steps (run_id, step_index);

-- -----------------------------------------------------------------------------
-- usage_events — append only
-- -----------------------------------------------------------------------------

create table public.usage_events (
  id                uuid primary key default gen_random_uuid(),
  org_id            uuid not null references public.organizations (id) on delete cascade,
  -- No cascade and no composite key to runs: a usage event outlives the run it
  -- came from, because it is what the organisation was charged for. Deleting a
  -- run must not erase the spend.
  run_id            uuid,
  step_id           uuid,
  provider          text not null check (length(provider) between 1 and 64),
  model             text not null check (length(model) between 1 and 120),
  -- Token counts and whatever else the provider reports. Shape varies by
  -- provider, which is why DATA_MODEL.md leaves it as jsonb.
  units_json        jsonb not null default '{}'::jsonb,
  cost_usd_micros   bigint not null check (cost_usd_micros >= 0),
  -- 'provider_reported' is authoritative; 'estimated' is our own rate-card
  -- arithmetic when the provider does not report cost. A bill built from
  -- estimates without saying so is a fabricated number.
  estimate_source   text not null default 'estimated'
                      check (estimate_source in ('provider_reported', 'estimated')),
  rate_card_version text check (rate_card_version is null or length(rate_card_version) <= 40),
  created_at        timestamptz not null default now()
);

create index usage_events_org_created_idx on public.usage_events (org_id, created_at desc);
create index usage_events_run_idx on public.usage_events (run_id) where run_id is not null;

-- -----------------------------------------------------------------------------
-- usage_reservations
--
-- DATA_MODEL.md: "unique active reservations per dispatch". Money is held
-- before the provider is called and released or settled afterwards, so two
-- concurrent runs cannot each see the same headroom and both spend it.
-- -----------------------------------------------------------------------------

create table public.usage_reservations (
  id              uuid primary key default gen_random_uuid(),
  org_id          uuid not null references public.organizations (id) on delete cascade,
  run_id          uuid not null,
  max_usd_micros  bigint not null check (max_usd_micros > 0),
  status          public.usage_reservation_status not null default 'active',
  expires_at      timestamptz not null,
  settled_at      timestamptz,
  created_at      timestamptz not null default now(),

  constraint usage_reservations_run_fk
    foreign key (org_id, run_id) references public.runs (org_id, id) on delete cascade
);

create unique index usage_reservations_one_active_per_run
  on public.usage_reservations (run_id)
  where status = 'active';

create index usage_reservations_sweep_idx
  on public.usage_reservations (expires_at)
  where status = 'active';

-- -----------------------------------------------------------------------------
-- usage_periods — the row the spend cap is enforced against
--
-- `subscription_id` is nullable until P5 exists. DATA_MODEL.md keys this by
-- (org_id, subscription_id, period_start); with no subscriptions table the key
-- is (org_id, period_start), which is the same thing for an organisation that
-- has one subscription — and every organisation has at most one until P5
-- introduces the concept at all.
--
-- This is the single row every dispatch locks. Keeping it one row per month per
-- organisation is what makes the lock cheap and the ordering total.
-- -----------------------------------------------------------------------------

create table public.usage_periods (
  org_id            uuid not null references public.organizations (id) on delete cascade,
  period_start      date not null,
  subscription_id   uuid,
  spent_usd_micros  bigint not null default 0 check (spent_usd_micros >= 0),
  reserved_usd_micros bigint not null default 0 check (reserved_usd_micros >= 0),
  updated_at        timestamptz not null default now(),

  primary key (org_id, period_start)
);


-- ===========================================================================
-- >>> 0014_runtime_rls.sql
-- ===========================================================================

-- =============================================================================
-- 0014_runtime_rls.sql — privileges and policies for the runtime tables
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
--
-- Customers READ their runs and WRITE none of them. Everything a run contains —
-- its status, its cost, its trace — is written by the execution plane, which
-- ARCHITECTURE.md keeps as a separate authority from the control plane. A
-- customer who could set `spent_usd_micros` could spend without paying, and one
-- who could set `status` could mark a failed run succeeded.
--
-- Dispatch and cancellation therefore go through RPCs in 0015, which check the
-- caller and the budget in the same transaction as the write.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- organizations.monthly_spend_cap_usd_micros
--
-- 0003 granted update on exactly (name, locale, timezone). A column added later
-- is not in that grant, so it is already unwritable by customers — this is here
-- to say so out loud, because "we never granted it" is easy to lose track of
-- after a few migrations, and the next person adding a column should see that
-- the question was asked.
-- -----------------------------------------------------------------------------

do $$
begin
  if has_column_privilege('authenticated', 'public.organizations',
                          'monthly_spend_cap_usd_micros', 'UPDATE') then
    raise exception
      'monthly_spend_cap_usd_micros is customer-updatable; it is the P3 spend cap and must not be';
  end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- runs
-- -----------------------------------------------------------------------------

alter table public.runs enable row level security;
revoke all on public.runs from anon, authenticated;
grant select on public.runs to authenticated;
grant select, insert, update on public.runs to service_role;

create policy runs_select on public.runs
  for select to authenticated
  using (public.is_org_member(org_id));

-- No INSERT, UPDATE or DELETE for any customer role. start_run() dispatches,
-- cancel_run() stops; both are in 0015 and both check the caller themselves.

-- -----------------------------------------------------------------------------
-- run_steps — the trace
-- -----------------------------------------------------------------------------

alter table public.run_steps enable row level security;
revoke all on public.run_steps from anon, authenticated;
grant select on public.run_steps to authenticated;
grant select, insert, update on public.run_steps to service_role;

-- A viewer sees the trace. It carries step kinds, models, costs and a pointer
-- to a redacted trace — never prompt or completion text, which is why
-- redacted_trace_ref is a reference and summary_json is bounded. Watching what
-- the workspace is doing is the whole of a viewer's job.
create policy run_steps_select on public.run_steps
  for select to authenticated
  using (public.is_org_member(org_id));

-- -----------------------------------------------------------------------------
-- usage_events — append only, and readable by those who answer for the bill
-- -----------------------------------------------------------------------------

alter table public.usage_events enable row level security;
revoke all on public.usage_events from anon, authenticated;
grant select on public.usage_events to authenticated;
grant select, insert on public.usage_events to service_role;

-- owner and admin only, matching audit_events in 0003. Per-call spend is
-- commercial information about the organisation, and P1 settled that viewers
-- and members do not see billing.
create policy usage_events_select on public.usage_events
  for select to authenticated
  using (public.has_org_role(org_id, array['owner', 'admin']::public.org_role[]));

-- -----------------------------------------------------------------------------
-- usage_reservations — internal accounting
--
-- Readable by nobody but the execution plane. A reservation is a number held
-- mid-flight; it is not a fact about the organisation yet, and exposing it
-- would show spend that may never happen.
-- -----------------------------------------------------------------------------

alter table public.usage_reservations enable row level security;
revoke all on public.usage_reservations from anon, authenticated;
grant select, insert, update on public.usage_reservations to service_role;

-- RLS on, zero policies, as with platform_admins in 0003.

-- -----------------------------------------------------------------------------
-- usage_periods — the totals the cap is enforced against
-- -----------------------------------------------------------------------------

alter table public.usage_periods enable row level security;
revoke all on public.usage_periods from anon, authenticated;
grant select on public.usage_periods to authenticated;
grant select, insert, update on public.usage_periods to service_role;

-- owner and admin, same reasoning as usage_events: this is the monthly bill in
-- aggregate. `org_usage_summary()` in 0015 is how a screen reads it, so the
-- period row and the cap arrive together rather than the UI joining them.
create policy usage_periods_select on public.usage_periods
  for select to authenticated
  using (public.has_org_role(org_id, array['owner', 'admin']::public.org_role[]));


-- ===========================================================================
-- >>> 0015_runtime_rpc.sql
-- ===========================================================================

-- =============================================================================
-- 0015_runtime_rpc.sql — dispatch, settlement and cancellation
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
--
-- ROADMAP.md's P3 gate: "per-tenant spend cap and idempotency pass". Both are
-- enforced here, inside the transaction that creates the run, because a cap
-- checked before the insert and a run created after it are two facts that can
-- disagree.
--
-- THE LOCK ORDER IS THE ORGANISATION ROW, ALWAYS FIRST.
--
-- `organizations` is already the serialisation point for the seat gate in
-- 0004. Reusing it here gives one total order per tenant across every
-- transaction that touches tenant-wide limits, which is what stops a deadlock
-- between a dispatch and a membership change. It also sidesteps the upsert race
-- on usage_periods: taking a lock on a row that is guaranteed to exist is
-- reliable, whereas `insert … on conflict do nothing` followed by
-- `select … for update` can see nothing at all when a concurrent transaction
-- has inserted the row but not yet committed.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- current_usage_period — one row per organisation per calendar month
-- -----------------------------------------------------------------------------

create or replace function public.current_usage_period()
returns date language sql stable
set search_path = ''
as $$
  select date_trunc('month', now() at time zone 'utc')::date;
$$;

-- -----------------------------------------------------------------------------
-- start_run — pin the version, reserve the budget, create the run
--
-- Returns {run_id, reused}. `reused` is true when an idempotency key matched an
-- existing run: ARCHITECTURE.md requires idempotency keys, and the point of one
-- is that a client which retries a dispatch it is unsure about gets the same
-- run back rather than a second one that also costs money.
-- -----------------------------------------------------------------------------

create or replace function public.start_run(
  p_agent_id        uuid,
  p_input           jsonb default '{}'::jsonb,
  p_idempotency_key text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid       uuid := (select auth.uid());
  v_org_id    uuid;
  v_status    public.agent_status;
  v_version   uuid;
  v_config    jsonb;
  v_budget    bigint;
  v_cap       bigint;
  v_period    date := public.current_usage_period();
  v_spent     bigint;
  v_reserved  bigint;
  v_run_id    uuid;
  v_existing  uuid;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'insufficient_privilege';
  end if;

  select a.org_id, a.status, a.active_version_id
    into v_org_id, v_status, v_version
  from public.agents a
  where a.id = p_agent_id;

  -- Unknown agent and someone else's agent answer alike, as everywhere else.
  if v_org_id is null
     or not public.has_org_role(
          v_org_id, array['owner', 'admin', 'member']::public.org_role[]
        ) then
    raise exception 'ORG_ACCESS_DENIED' using errcode = 'insufficient_privilege';
  end if;

  if v_status = 'archived' then
    raise exception 'AGENT_ARCHIVED' using errcode = 'invalid_parameter_value';
  end if;

  -- CLAUDE.md rule 8: runs execute a published version pin. A draft is not
  -- runnable, however complete it looks in the editor.
  if v_version is null then
    raise exception 'AGENT_VERSION_MISSING' using errcode = 'no_data_found';
  end if;

  -- Idempotency, checked before the lock so a retry is cheap.
  if p_idempotency_key is not null then
    select r.id into v_existing
    from public.runs r
    where r.org_id = v_org_id and r.idempotency_key = p_idempotency_key;
    if v_existing is not null then
      return jsonb_build_object('run_id', v_existing, 'reused', true);
    end if;
  end if;

  -- The serialisation point. Everything below reads tenant-wide totals that a
  -- concurrent dispatch would otherwise be changing underneath it.
  select o.monthly_spend_cap_usd_micros into v_cap
  from public.organizations o
  where o.id = v_org_id
  for update;

  select (v.config_json ->> 'maxSpendUsdMicros')::bigint into v_budget
  from public.agent_versions v
  where v.id = v_version;

  if v_budget is null or v_budget <= 0 then
    -- A published version with no spend cap would be a run with no ceiling.
    raise exception 'AGENT_CONFIG_INVALID' using errcode = 'invalid_parameter_value';
  end if;

  insert into public.usage_periods (org_id, period_start)
  values (v_org_id, v_period)
  on conflict (org_id, period_start) do nothing;

  select p.spent_usd_micros, p.reserved_usd_micros into v_spent, v_reserved
  from public.usage_periods p
  where p.org_id = v_org_id and p.period_start = v_period;

  -- Reserved counts against the cap as well as spent. Without that, N runs
  -- dispatched before any of them settles would each see the same headroom —
  -- the same hole the seat gate closes by counting pending invitations.
  if v_spent + v_reserved + v_budget > v_cap then
    raise exception 'USAGE_LIMIT_REACHED' using errcode = 'insufficient_resources';
  end if;

  insert into public.runs
    (org_id, agent_id, agent_version_id, initiator_user_id, input_json,
     idempotency_key, budget_usd_micros)
  values
    (v_org_id, p_agent_id, v_version, v_uid, coalesce(p_input, '{}'::jsonb),
     p_idempotency_key, v_budget)
  returning id into v_run_id;

  insert into public.usage_reservations (org_id, run_id, max_usd_micros, expires_at)
  values (v_org_id, v_run_id, v_budget, now() + interval '1 hour');

  update public.usage_periods
  set reserved_usd_micros = reserved_usd_micros + v_budget, updated_at = now()
  where org_id = v_org_id and period_start = v_period;

  perform public.log_audit(
    v_org_id, 'user', 'run.started', 'run', v_run_id,
    jsonb_build_object('agent_id', p_agent_id, 'agent_version_id', v_version,
                       'budget_usd_micros', v_budget)
  );

  return jsonb_build_object('run_id', v_run_id, 'reused', false);
exception
  when unique_violation then
    -- Two concurrent dispatches with the same idempotency key. One won; return
    -- its run rather than an error the caller cannot act on. Re-raised if the
    -- violation was something else, because swallowing it would hide a bug.
    if p_idempotency_key is null then raise; end if;
    select r.id into v_existing
    from public.runs r
    where r.org_id = v_org_id and r.idempotency_key = p_idempotency_key;
    if v_existing is null then raise; end if;
    return jsonb_build_object('run_id', v_existing, 'reused', true);
end;
$$;

-- -----------------------------------------------------------------------------
-- settle_run — the execution plane reports what actually happened
--
-- service_role only. This writes spend, so a customer-reachable version of it
-- would be a way to spend without paying, or to mark a failed run succeeded.
-- -----------------------------------------------------------------------------

create or replace function public.settle_run(
  p_run_id     uuid,
  p_status     public.run_status,
  p_cost_usd_micros bigint,
  p_result     jsonb default null,
  p_error_code text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org_id   uuid;
  v_period   date;
  v_reserved bigint;
begin
  if p_status not in ('succeeded', 'failed', 'cancelled') then
    raise exception 'VALIDATION_FAILED' using errcode = 'invalid_parameter_value',
      detail = 'settle_run finalises a run; use it only for a terminal status.';
  end if;
  if p_cost_usd_micros < 0 then
    raise exception 'VALIDATION_FAILED' using errcode = 'invalid_parameter_value';
  end if;

  select r.org_id into v_org_id from public.runs r where r.id = p_run_id;
  if v_org_id is null then
    raise exception 'RUN_NOT_FOUND' using errcode = 'no_data_found';
  end if;

  perform 1 from public.organizations o where o.id = v_org_id for update;

  -- Settle the reservation first: the amount released is whatever it was
  -- holding, which is not necessarily this run's budget if a sweeper already
  -- expired it. Taking the figure from the row rather than from the run is what
  -- keeps the period total from drifting.
  update public.usage_reservations
  set status = 'settled', settled_at = now()
  where run_id = p_run_id and status = 'active'
  returning max_usd_micros into v_reserved;

  v_period := public.current_usage_period();

  update public.usage_periods
  set reserved_usd_micros = greatest(reserved_usd_micros - coalesce(v_reserved, 0), 0),
      spent_usd_micros = spent_usd_micros + p_cost_usd_micros,
      updated_at = now()
  where org_id = v_org_id and period_start = v_period;

  update public.runs
  set status = p_status,
      spent_usd_micros = p_cost_usd_micros,
      result_json = p_result,
      error_code = p_error_code,
      ended_at = now(),
      started_at = coalesce(started_at, now())
  where id = p_run_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- cancel_run — stop a run and give the budget back
-- -----------------------------------------------------------------------------

create or replace function public.cancel_run(p_run_id uuid)
returns public.run_status
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid      uuid := (select auth.uid());
  v_org_id   uuid;
  v_status   public.run_status;
  v_reserved bigint;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'insufficient_privilege';
  end if;

  select r.org_id, r.status into v_org_id, v_status
  from public.runs r where r.id = p_run_id;

  if v_org_id is null
     or not public.has_org_role(
          v_org_id, array['owner', 'admin', 'member']::public.org_role[]
        ) then
    raise exception 'ORG_ACCESS_DENIED' using errcode = 'insufficient_privilege';
  end if;

  if v_status not in ('queued', 'running', 'awaiting_approval') then
    -- Already finished. Not an error worth raising — the caller wanted it
    -- stopped and it is stopped — but the status says it was not this call.
    return v_status;
  end if;

  perform 1 from public.organizations o where o.id = v_org_id for update;

  update public.usage_reservations
  set status = 'released', settled_at = now()
  where run_id = p_run_id and status = 'active'
  returning max_usd_micros into v_reserved;

  update public.usage_periods
  set reserved_usd_micros = greatest(reserved_usd_micros - coalesce(v_reserved, 0), 0),
      updated_at = now()
  where org_id = v_org_id and period_start = public.current_usage_period();

  update public.runs
  set status = 'cancelled', ended_at = now()
  where id = p_run_id;

  perform public.log_audit(v_org_id, 'user', 'run.cancelled', 'run', p_run_id, '{}'::jsonb);

  return 'cancelled'::public.run_status;
end;
$$;

-- -----------------------------------------------------------------------------
-- expire_stale_reservations — reclaim budget a crashed worker is holding
--
-- Without this, a worker that dies mid-run holds its reservation forever and
-- the organisation's cap shrinks by that much permanently. service_role only;
-- it is a maintenance task, not a customer action.
-- -----------------------------------------------------------------------------

create or replace function public.expire_stale_reservations()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count integer := 0;
  v_row   record;
begin
  for v_row in
    select id, org_id, max_usd_micros
    from public.usage_reservations
    where status = 'active' and expires_at < now()
    order by org_id
    for update skip locked
  loop
    update public.usage_reservations
    set status = 'expired', settled_at = now()
    where id = v_row.id;

    update public.usage_periods
    set reserved_usd_micros = greatest(reserved_usd_micros - v_row.max_usd_micros, 0),
        updated_at = now()
    where org_id = v_row.org_id and period_start = public.current_usage_period();

    -- The run is finished as far as anyone can tell: nothing is going to report
    -- on it. Left 'running', it would sit in the UI forever.
    update public.runs
    set status = 'failed', error_code = 'RUN_ABANDONED', ended_at = now()
    where id = (select run_id from public.usage_reservations where id = v_row.id)
      and status in ('queued', 'running', 'awaiting_approval');

    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;

-- -----------------------------------------------------------------------------
-- org_usage_summary — the numbers a billing screen shows
--
-- Membership-checked, for the same reason org_seat_usage is: a function that
-- takes any organisation id and returns its spend is a commercial-intelligence
-- oracle for every other tenant.
-- -----------------------------------------------------------------------------

create or replace function public.org_usage_summary(p_org_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_cap bigint;
  v_row record;
begin
  if not public.has_org_role(p_org_id, array['owner', 'admin']::public.org_role[]) then
    raise exception 'ORG_ACCESS_DENIED' using errcode = 'insufficient_privilege';
  end if;

  select o.monthly_spend_cap_usd_micros into v_cap
  from public.organizations o where o.id = p_org_id;

  select coalesce(p.spent_usd_micros, 0) as spent,
         coalesce(p.reserved_usd_micros, 0) as reserved
  into v_row
  from (select 1) one
  left join public.usage_periods p
    on p.org_id = p_org_id and p.period_start = public.current_usage_period();

  return jsonb_build_object(
    'periodStart', public.current_usage_period(),
    'capUsdMicros', v_cap,
    'spentUsdMicros', coalesce(v_row.spent, 0),
    'reservedUsdMicros', coalesce(v_row.reserved, 0)
  );
end;
$$;

-- -----------------------------------------------------------------------------
-- Execute privileges
-- -----------------------------------------------------------------------------

revoke execute on function public.current_usage_period() from public;
revoke execute on function public.start_run(uuid, jsonb, text) from public;
revoke execute on function public.settle_run(uuid, public.run_status, bigint, jsonb, text)
  from public, anon, authenticated;
revoke execute on function public.cancel_run(uuid) from public;
revoke execute on function public.expire_stale_reservations() from public, anon, authenticated;
revoke execute on function public.org_usage_summary(uuid) from public;

grant execute on function public.current_usage_period() to authenticated, service_role;
grant execute on function public.start_run(uuid, jsonb, text) to authenticated;
grant execute on function public.cancel_run(uuid) to authenticated;
grant execute on function public.org_usage_summary(uuid) to authenticated;

-- The execution plane only. These write spend.
grant execute on function public.settle_run(uuid, public.run_status, bigint, jsonb, text)
  to service_role;
grant execute on function public.expire_stale_reservations() to service_role;


-- ===========================================================================
-- >>> 0016_suspension.sql
-- ===========================================================================

-- =============================================================================
-- 0016_suspension.sql — make suspension actually suspend something
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
--
-- `organizations.status` has existed since 0001 and `SUPER_ADMIN.md` lists
-- "suspend account from new runs with reason, warning and safety audit" as a
-- safeguard. Nothing checked the column. A suspended organisation could
-- dispatch runs and spend money exactly as before, and the only effect of
-- suspending one was a different word on an admin screen.
--
-- This file closes that, and adds the two things the safeguard names and the
-- schema could not express: a reason, and when it happened.
--
-- WHAT SUSPENSION DOES AND DOES NOT DO.
--
-- It blocks new runs. It does NOT block reading, editing drafts, or managing
-- the team. That is deliberate: `SUPER_ADMIN.md` says "suspend account from new
-- runs" and separately forbids silently deleting account or content, and a
-- suspension that locked a customer out of their own data would be closer to
-- the second than the first. A suspended organisation can see everything it
-- had, fix whatever caused the suspension, and export — it simply cannot spend
-- money.
-- =============================================================================

alter table public.organizations
  add column suspended_at timestamptz,
  add column suspension_reason text
    check (suspension_reason is null or length(trim(suspension_reason)) between 3 and 500);

-- The three facts move together or not at all. Without this, "suspended with no
-- reason and no date" is representable, and that is precisely the record an
-- audit asks for and cannot find.
alter table public.organizations
  add constraint organizations_suspension_consistent check (
    (status = 'suspended') = (suspended_at is not null)
    and (suspended_at is null) = (suspension_reason is null)
  );

comment on column public.organizations.suspension_reason is
  'Shown to the customer. SUPER_ADMIN.md requires a reason and a warning, so this '
  'is deliberately readable by members rather than admin-only: a workspace that '
  'stops working without saying why is an outage, not a suspension.';

-- Customers still cannot write any of it: 0003 grants update on exactly
-- (name, locale, timezone), and a column added later is not in that grant.
-- Stated as an executable check rather than a comment, because "we never
-- granted it" is easy to lose track of after sixteen migrations.
do $$
begin
  if has_column_privilege('authenticated', 'public.organizations', 'status', 'UPDATE')
     or has_column_privilege('authenticated', 'public.organizations', 'suspended_at', 'UPDATE')
     or has_column_privilege('authenticated', 'public.organizations', 'suspension_reason', 'UPDATE')
  then
    raise exception 'suspension columns are customer-updatable; they are a platform safety control';
  end if;
end;
$$;

-- The platform-admin module writes these, and only these. An explicit grant
-- rather than relying on the service role's default privileges: defaults are a
-- property of how the project was provisioned, and this is a safety control.
grant update (status, suspended_at, suspension_reason) on public.organizations to service_role;

-- -----------------------------------------------------------------------------
-- start_run — supersedes the definition in 0015
--
-- Replaced in full rather than patched, because that is the only way a
-- function changes. The single difference from 0015 is the suspension check
-- below, marked where it sits.
-- -----------------------------------------------------------------------------

create or replace function public.start_run(
  p_agent_id        uuid,
  p_input           jsonb default '{}'::jsonb,
  p_idempotency_key text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid       uuid := (select auth.uid());
  v_org_id    uuid;
  v_status    public.agent_status;
  v_version   uuid;
  v_budget    bigint;
  v_cap       bigint;
  v_org_state public.org_status;
  v_period    date := public.current_usage_period();
  v_spent     bigint;
  v_reserved  bigint;
  v_run_id    uuid;
  v_existing  uuid;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'insufficient_privilege';
  end if;

  select a.org_id, a.status, a.active_version_id
    into v_org_id, v_status, v_version
  from public.agents a
  where a.id = p_agent_id;

  if v_org_id is null
     or not public.has_org_role(
          v_org_id, array['owner', 'admin', 'member']::public.org_role[]
        ) then
    raise exception 'ORG_ACCESS_DENIED' using errcode = 'insufficient_privilege';
  end if;

  if v_status = 'archived' then
    raise exception 'AGENT_ARCHIVED' using errcode = 'invalid_parameter_value';
  end if;

  if v_version is null then
    raise exception 'AGENT_VERSION_MISSING' using errcode = 'no_data_found';
  end if;

  if p_idempotency_key is not null then
    select r.id into v_existing
    from public.runs r
    where r.org_id = v_org_id and r.idempotency_key = p_idempotency_key;
    if v_existing is not null then
      return jsonb_build_object('run_id', v_existing, 'reused', true);
    end if;
  end if;

  select o.monthly_spend_cap_usd_micros, o.status into v_cap, v_org_state
  from public.organizations o
  where o.id = v_org_id
  for update;

  -- ++ THE CHANGE IN THIS MIGRATION ++
  -- Checked under the same lock as the budget, so a suspension committed while
  -- a dispatch is in flight cannot be stepped over. A distinct code, because
  -- "your workspace is suspended" is something the customer can act on and
  -- ORG_ACCESS_DENIED is not.
  if v_org_state = 'suspended' then
    raise exception 'ORG_SUSPENDED' using errcode = 'insufficient_privilege';
  end if;

  select (v.config_json ->> 'maxSpendUsdMicros')::bigint into v_budget
  from public.agent_versions v
  where v.id = v_version;

  if v_budget is null or v_budget <= 0 then
    raise exception 'AGENT_CONFIG_INVALID' using errcode = 'invalid_parameter_value';
  end if;

  insert into public.usage_periods (org_id, period_start)
  values (v_org_id, v_period)
  on conflict (org_id, period_start) do nothing;

  select p.spent_usd_micros, p.reserved_usd_micros into v_spent, v_reserved
  from public.usage_periods p
  where p.org_id = v_org_id and p.period_start = v_period;

  if v_spent + v_reserved + v_budget > v_cap then
    raise exception 'USAGE_LIMIT_REACHED' using errcode = 'insufficient_resources';
  end if;

  insert into public.runs
    (org_id, agent_id, agent_version_id, initiator_user_id, input_json,
     idempotency_key, budget_usd_micros)
  values
    (v_org_id, p_agent_id, v_version, v_uid, coalesce(p_input, '{}'::jsonb),
     p_idempotency_key, v_budget)
  returning id into v_run_id;

  insert into public.usage_reservations (org_id, run_id, max_usd_micros, expires_at)
  values (v_org_id, v_run_id, v_budget, now() + interval '1 hour');

  update public.usage_periods
  set reserved_usd_micros = reserved_usd_micros + v_budget, updated_at = now()
  where org_id = v_org_id and period_start = v_period;

  perform public.log_audit(
    v_org_id, 'user', 'run.started', 'run', v_run_id,
    jsonb_build_object('agent_id', p_agent_id, 'agent_version_id', v_version,
                       'budget_usd_micros', v_budget)
  );

  return jsonb_build_object('run_id', v_run_id, 'reused', false);
exception
  when unique_violation then
    if p_idempotency_key is null then raise; end if;
    select r.id into v_existing
    from public.runs r
    where r.org_id = v_org_id and r.idempotency_key = p_idempotency_key;
    if v_existing is null then raise; end if;
    return jsonb_build_object('run_id', v_existing, 'reused', true);
end;
$$;

-- -----------------------------------------------------------------------------
-- set_org_suspended — the platform's safety control
--
-- service_role only. This is not a customer action in any role, including
-- owner: an organisation that could unsuspend itself is not suspended.
--
-- The acting administrator is an argument rather than auth.uid(), because this
-- connection has no JWT. Same reason log_platform_audit takes one.
-- -----------------------------------------------------------------------------

create or replace function public.set_org_suspended(
  p_actor_user_id uuid,
  p_org_id        uuid,
  p_suspended     boolean,
  p_reason        text default null
)
returns public.org_status
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_new    public.org_status;
begin
  if p_actor_user_id is null then
    raise exception 'PLATFORM_AUDIT_REQUIRES_ACTOR' using errcode = 'invalid_parameter_value';
  end if;

  if p_suspended and (v_reason is null or length(v_reason) < 3) then
    -- SUPER_ADMIN.md requires a reason. Enforced here rather than in the
    -- application so there is no path that suspends without one.
    raise exception 'SUSPENSION_REQUIRES_REASON' using errcode = 'invalid_parameter_value';
  end if;

  if not exists (select 1 from public.organizations o where o.id = p_org_id) then
    raise exception 'ORG_NOT_FOUND' using errcode = 'no_data_found';
  end if;

  v_new := case when p_suspended then 'suspended' else 'active' end::public.org_status;

  update public.organizations
  set status = v_new,
      suspended_at = case when p_suspended then now() else null end,
      suspension_reason = case when p_suspended then v_reason else null end
  where id = p_org_id;

  -- Argument order is (actor, action, entity_type, org_id, entity_id, metadata).
  perform public.log_platform_audit(
    p_actor_user_id,
    case when p_suspended then 'admin.org.suspended' else 'admin.org.restored' end,
    'organization',
    p_org_id,
    p_org_id,
    -- The reason is recorded. It is operator-written text about an account, not
    -- customer content, and an audit record of a suspension without its reason
    -- is the record that cannot answer the question it exists for.
    jsonb_build_object('reason', v_reason)
  );

  return v_new;
end;
$$;

revoke execute on function public.set_org_suspended(uuid, uuid, boolean, text)
  from public, anon, authenticated;
grant execute on function public.set_org_suspended(uuid, uuid, boolean, text) to service_role;


-- ===========================================================================
-- >>> 0017_revoke_anon_execute.sql
-- ===========================================================================

-- =============================================================================
-- 0017_revoke_anon_execute.sql — anon may call no function
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
--
-- WHY THIS EXISTS
--
-- A real Supabase project ships with default privileges that grant EXECUTE on
-- every new function in `public` to anon and authenticated DIRECTLY:
--
--   alter default privileges in schema public
--     grant execute on functions to anon, authenticated, service_role;
--
-- Twelve functions in 0005-0016 revoked EXECUTE only from PUBLIC. That removes
-- PostgreSQL's implicit grant and leaves Supabase's explicit one untouched, so
-- on Supabase each of them would have been callable by an anonymous visitor.
--
-- None of the twelve was exploitable. Each checks auth.uid() first and raises
-- AUTH_REQUIRED, so an anonymous call reached the body and was refused there.
-- But that is one layer where there should be two, and the local verification
-- cluster could not show it: its shim did not reproduce Supabase's default
-- privileges, so every "anon cannot execute" assertion was passing for the
-- wrong reason. The shim now does, and tests/db/rls-suite.mjs group 14 failed
-- against these twelve before this file and passes after it.
--
-- A separate file rather than edits to 0005-0016, deliberately. Nothing has
-- been applied to Supabase, so editing in place would have been possible - but
-- it would also silently invalidate any review of those files already done.
-- One file that says what changed and why is the version a reviewer can trust.
--
-- WHAT IT DOES NOT CHANGE
--
-- authenticated keeps every grant it had: these RPCs exist to be called by
-- signed-in users. No table, row, policy or data is touched. Re-running it is
-- harmless: revoking a privilege that is not held is a no-op.
-- =============================================================================

revoke execute on function public.accept_invitation(bytea) from anon;
revoke execute on function public.cancel_run(uuid) from anon;
revoke execute on function public.create_agent(uuid, text, text) from anon;
revoke execute on function public.create_organization(text, text) from anon;
revoke execute on function public.current_usage_period() from anon;
revoke execute on function public.expire_stale_invitations(uuid) from anon;
revoke execute on function public.install_template(uuid, uuid, text) from anon;
revoke execute on function public.org_usage_summary(uuid) from anon;
revoke execute on function public.publish_agent_version(uuid) from anon;
revoke execute on function public.set_agent_archived(uuid, boolean) from anon;
revoke execute on function public.start_run(uuid, jsonb, text) from anon;
revoke execute on function public.transfer_ownership(uuid, uuid) from anon;

-- A function added later without its own revoke would reopen this. Stop the
-- migration rather than let that ship: this block fails the transaction if any
-- non-trigger function in public is still executable by anon.
do $$
declare
  v_open text;
begin
  select string_agg(p.proname, ', ' order by p.proname) into v_open
  from pg_proc p
  join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and p.prorettype <> 'trigger'::regtype
    and has_function_privilege('anon', p.oid, 'EXECUTE');

  if v_open is not null then
    raise exception 'anon can still execute: %', v_open;
  end if;
end;
$$;


-- ===========================================================================
-- >>> 0018_backfill_profiles.sql
-- ===========================================================================

-- =============================================================================
-- 0018_backfill_profiles.sql — a profile for every user who signed up early
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
--
-- WHY THIS EXISTS
--
-- `handle_new_user()` (0004) creates a public.profiles row whenever a row is
-- inserted into auth.users. It is a trigger, so it only sees users created
-- AFTER it exists.
--
-- On the AgentOS-Development project, people signed up through the preview
-- deployment before any migration had been applied. Their auth.users rows
-- exist; the trigger did not, so they have no profile. Reproduced locally: such
-- a user creates an organisation, holds one real membership as its owner, and
-- the team screen - which joins memberships to profiles - shows ZERO members.
-- The dashboard's member count reads the same list.
--
-- This inserts the missing rows, using exactly the naming rule the trigger uses
-- (display_name from sign-up metadata, else the email's local part, else
-- "user", capped at 80 characters), so a backfilled profile is
-- indistinguishable from one the trigger would have made.
--
-- DATA IT CHANGES
--
-- Inserts only. It adds a profiles row for each auth.users row that has none,
-- and touches no existing row in any table. `on conflict do nothing` makes it
-- safe to run more than once. On a project with no users it does nothing.
--
-- It reads `raw_user_meta_data` and `email` from auth.users, which only this
-- migration's owner can see; neither value is copied anywhere except the
-- display name that the trigger would have written anyway.
-- =============================================================================

insert into public.profiles (user_id, display_name)
select
  u.id,
  left(
    coalesce(
      nullif(btrim(u.raw_user_meta_data ->> 'display_name'), ''),
      nullif(split_part(coalesce(u.email, ''), '@', 1), ''),
      'user'
    ),
    80
  )
from auth.users u
where not exists (select 1 from public.profiles p where p.user_id = u.id)
on conflict (user_id) do nothing;


-- =============================================================================
-- Post-check, inside the transaction. Any failure here rolls back everything.
-- =============================================================================
do $$
declare
  v_missing text;
  v_open    text;
begin
  select string_agg(t, ', ') into v_missing
  from unnest(array[
    'organizations','memberships','profiles','invitations','platform_admins',
    'audit_events','agents','agent_versions','global_templates',
    'global_template_versions','template_installations','runs','run_steps',
    'usage_events','usage_reservations','usage_periods'
  ]) as t
  where to_regclass('public.' || t) is null;

  if v_missing is not null then
    raise exception 'post-check: missing tables: %', v_missing;
  end if;

  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                 where n.nspname = 'public' and p.proname = 'create_organization') then
    raise exception 'post-check: create_organization was not created';
  end if;

  select string_agg(p.proname, ', ') into v_open
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and p.prorettype <> 'trigger'::regtype
    and has_function_privilege('anon', p.oid, 'EXECUTE');
  if v_open is not null then
    raise exception 'post-check: anon can execute: %', v_open;
  end if;
end;
$$;

commit;

-- Reaching this line means every migration applied and every check passed.
